function backfillExcavatorFinance(){try{const assets=db.prepare('SELECT id,business_unit_id,asset_no FROM excavator_assets').all();for(const a of assets){db.prepare('SELECT id,amount,payment_type,method,reference,receipt_file,created_by FROM excavator_payments WHERE asset_id=?').all(a.id).forEach(p=>financeSync({businessUnitId:a.business_unit_id,type:p.payment_type==='Sale'?'Revenue':'Expense',category:'Excavator '+p.payment_type+' Payment',amount:p.amount,description:'Excavator '+p.payment_type+' payment for '+a.asset_no,paymentMethod:p.method,reference:p.reference,createdBy:p.created_by,sourceType:'Excavator Payment',sourceId:p.id,receiptFile:p.receipt_file}));db.prepare('SELECT id,amount,description,vendor,attachment_file,created_by FROM excavator_repairs WHERE asset_id=?').all(a.id).forEach(r=>financeSync({businessUnitId:a.business_unit_id,category:'Repair / Maintenance',amount:r.amount,description:a.asset_no+' repair: '+(r.description||'Repair')+(r.vendor?' · '+r.vendor:''),createdBy:r.created_by,sourceType:'Excavator Repair',sourceId:r.id,receiptFile:r.attachment_file}));db.prepare('SELECT id,amount,provider,origin,destination,attachment_file,created_by FROM excavator_logistics WHERE asset_id=?').all(a.id).forEach(l=>financeSync({businessUnitId:a.business_unit_id,category:'Transport / Logistics',amount:l.amount,description:(a.asset_no+' logistics: '+(l.provider||'')+' '+(l.origin||'')+' → '+(l.destination||'')).trim(),createdBy:l.created_by,sourceType:'Excavator Logistics',sourceId:l.id,receiptFile:l.attachment_file}));db.prepare('SELECT id,cost,part_name,quantity,attachment_file,created_by FROM excavator_parts WHERE asset_id=? AND COALESCE(cost,0)>0').all(a.id).forEach(p=>financeSync({businessUnitId:a.business_unit_id,category:'Parts / Spare Parts',amount:Number(p.cost||0)*Number(p.quantity||1),description:a.asset_no+' parts: '+p.part_name,createdBy:p.created_by,sourceType:'Excavator Part',sourceId:p.id,receiptFile:p.attachment_file}));db.prepare("SELECT id,type,amount,counterparty,status,metadata,created_by FROM excavator_transactions WHERE asset_id=? AND type IN ('Customs Duty','Tax / VAT','Shipping / Freight','Commission','Documentation / Clearance','Other Cost','Purchase','Logistics','Repair','Part Purchase')").all(a.id).forEach(t=>{let m={};try{m=t.metadata?JSON.parse(t.metadata):{}}catch(_){}if(t.status!=='Cancelled'&&m.finance_sync!==false)financeSync({businessUnitId:a.business_unit_id,category:t.type,amount:t.amount,description:a.asset_no+' '+t.type+(t.counterparty?' · '+t.counterparty:''),createdBy:t.created_by,sourceType:'Excavator Cost Transaction',sourceId:t.id})})}}catch(e){console.error('Excavator finance backfill:',e.message)}}
backfillExcavatorFinance();
