app.get('/api/dashboard',auth,allow('dashboard'),(req,res)=>{
  try {
    const scope=unitScope(req,'business_unit_id');
    const suffix=scope.sql;
    const args=scope.args;
    const rev=db.prepare(`SELECT COALESCE(SUM(amount),0) v FROM finance_entries WHERE type='Revenue' AND status!='Voided'${suffix}`).get(...args).v;
    const exp=db.prepare(`SELECT COALESCE(SUM(amount),0) v FROM finance_entries WHERE type='Expense' AND status!='Voided'${suffix}`).get(...args).v;
    const sales=db.prepare(`SELECT COALESCE(SUM(total),0) v FROM sales WHERE status='Completed'${suffix}`).get(...args).v;
    const gp=db.prepare(`SELECT COALESCE(SUM(gross_profit),0) v FROM sales WHERE status='Completed'${suffix}`).get(...args).v;
    const pending=db.prepare(`SELECT COUNT(*) c FROM approvals WHERE status='Pending'${suffix}`).get(...args).c;
    const overdue=db.prepare(`SELECT COUNT(*) c FROM tasks WHERE status NOT IN ('Completed','Cancelled') AND due_date IS NOT NULL AND date(due_date)<date('now')${suffix}`).get(...args).c;
    const low=db.prepare(`SELECT COUNT(*) c FROM products WHERE active=1 AND item_type='PRODUCT' AND current_stock<=reorder_level${suffix}`).get(...args).c;
    const nscope=req.selected_business_unit_id?{sql:' OR business_unit_id=?',args:[req.selected_business_unit_id]}:(req.user.role==='CEO / Owner'?{sql:'',args:[]}:{sql:' OR business_unit_id=?',args:[req.user.business_unit_id]});const unread=db.prepare(`SELECT COUNT(*) c FROM notifications WHERE (user_id IS NULL OR user_id=?) AND read_at IS NULL AND (business_unit_id IS NULL${nscope.sql})`).get(req.user.id,...nscope.args).c;
    const units=db.prepare(`SELECT b.id,b.name,b.status,
      COALESCE((SELECT SUM(total) FROM sales s WHERE s.business_unit_id=b.id AND s.status='Completed'),0) sales,
      COALESCE((SELECT SUM(gross_profit) FROM sales s WHERE s.business_unit_id=b.id AND s.status='Completed'),0) gross_profit,
      COALESCE((SELECT SUM(amount) FROM finance_entries f WHERE f.business_unit_id=b.id AND f.type='Expense' AND f.status!='Voided'),0) expenses,
      COALESCE((SELECT SUM(p.current_stock*p.cost_price) FROM products p WHERE p.business_unit_id=b.id AND p.active=1),0) inventory_value
      FROM business_units b WHERE b.status!='Archived' ORDER BY b.name`).all();
    res.json({revenue:rev,expenses:exp,net:rev-exp,sales,gross_profit:gp,pending,overdue,low,unread,units,selected_business_unit_id:req.selected_business_unit_id,scope:req.user.role==='CEO / Owner'?(req.selected_business_unit_id?'unit':'all'):'unit'});
  } catch(e) {
    console.error('Dashboard error:',e);
    res.status(500).json({error:'Dashboard data could not be loaded: '+e.message});
  }
});
