// V27 — unit-scoped work/task management and evidence trail.
function taskAccessible(req,t){
  if(!t)return false;
  if(!enforceUnit(req,t.business_unit_id||0))return false;
  if(isWorkManager(req.user))return true;
  return Number(t.owner_id)===Number(req.user.id);
}
app.get('/api/tasks',auth,allow('tasks','performance'),(req,res)=>{
  let q=`SELECT t.*,u.name owner,u.role owner_role,b.name business_unit,ab.name assigned_by_name,rv.name reviewed_by_name
    FROM tasks t JOIN users u ON u.id=t.owner_id
    LEFT JOIN business_units b ON b.id=t.business_unit_id
    LEFT JOIN users ab ON ab.id=COALESCE(t.assigned_by,t.created_by)
    LEFT JOIN users rv ON rv.id=t.reviewed_by WHERE 1=1`;
  const sc=unitScope(req,'t.business_unit_id');q+=sc.sql;const args=[...sc.args];
  if(!isWorkManager(req.user)){q+=' AND t.owner_id=?';args.push(req.user.id)}
  if(req.query.owner_id){if(!isWorkManager(req.user)&&Number(req.query.owner_id)!==Number(req.user.id))return res.status(403).json({error:'You can only view your own work.'});q+=' AND t.owner_id=?';args.push(Number(req.query.owner_id))}
  if(req.query.status){q+=' AND t.status=?';args.push(String(req.query.status))}
  const rows=db.prepare(q+` ORDER BY CASE t.priority WHEN 'Critical' THEN 1 WHEN 'High' THEN 2 WHEN 'Normal' THEN 3 ELSE 4 END,
    CASE WHEN t.status IN ('Completed','Cancelled') THEN 1 ELSE 0 END,date(t.due_date),t.id DESC`).all(...args);
  res.json(rows.map(x=>({...x,attachments:(()=>{try{return JSON.parse(x.attachments_json||'[]')}catch(_){return[]}})()})));
});
app.post('/api/tasks',auth,allow('tasks','performance'),upload.array('attachments',10),(req,res)=>{
  if(!isWorkManager(req.user))return res.status(403).json({error:'Only CEO or authorized managers can create and assign work.'});
  const businessUnitId=Number(req.body.business_unit_id||currentUnit(req));
  if(!businessUnitId||!enforceUnit(req,businessUnitId))return res.status(403).json({error:'Task must belong to your current/authorized business unit.'});
  const ownerId=Number(req.body.owner_id||0),owner=db.prepare('SELECT id,name,role,business_unit_id,active FROM users WHERE id=?').get(ownerId);
  if(!owner||!owner.active)return res.status(400).json({error:'Select an active employee/user.'});
  if(Number(owner.business_unit_id)!==businessUnitId)return res.status(400).json({error:'Assigned user must belong to the same business unit.'});
  const title=String(req.body.title||'').trim();if(!title)return res.status(400).json({error:'Task title is required.'});
  const complexity=['Simple','Medium','Complex','Critical'].includes(req.body.complexity)?req.body.complexity:'Medium';
  const points=Number(req.body.work_points||({Simple:1,Medium:2,Complex:4,Critical:6}[complexity]));
  const files=(req.files||[]).map(f=>({name:f.originalname,path:'/uploads/'+f.filename,mime:f.mimetype,size:f.size}));
  const reviewRequired=String(req.body.review_required||'0')==='1'||req.body.review_required===true;
  const r=db.prepare(`INSERT INTO tasks(title,owner_id,business_unit_id,priority,status,due_date,expected_result,recurring,created_by,
      description,complexity,work_points,progress_percent,related_module,related_entity_type,related_entity_id,attachments_json,
      review_required,review_status,assigned_by,updated_at)
    VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP)`)
    .run(title,ownerId,businessUnitId,req.body.priority||'Normal','Not Started',req.body.due_date||null,req.body.expected_result||'',
      req.body.recurring||'None',req.user.id,req.body.description||'',complexity,Math.max(0,points),0,req.body.related_module||'',
      req.body.related_entity_type||'',req.body.related_entity_id?Number(req.body.related_entity_id):null,JSON.stringify(files),
      reviewRequired?1:0,reviewRequired?'Pending':'Not Required',req.user.id);
  db.prepare('INSERT INTO task_history(task_id,user_id,action,note) VALUES(?,?,?,?)').run(r.lastInsertRowid,req.user.id,'Assigned',JSON.stringify({owner_id:ownerId,due_date:req.body.due_date||null,priority:req.body.priority||'Normal',complexity,work_points:points}));
  notify(ownerId,'info','New work assigned',title,businessUnitId,'task',r.lastInsertRowid,'tasks');
  audit(req.user,'task',r.lastInsertRowid,'assign',JSON.stringify({title,owner_id:ownerId,business_unit_id:businessUnitId}));
  res.json({id:r.lastInsertRowid});
});
app.get('/api/tasks/:id/detail',auth,allow('tasks','performance'),(req,res)=>{
  const t=db.prepare(`SELECT t.*,u.name owner,u.role owner_role,b.name business_unit,ab.name assigned_by_name,rv.name reviewed_by_name
    FROM tasks t JOIN users u ON u.id=t.owner_id LEFT JOIN business_units b ON b.id=t.business_unit_id
    LEFT JOIN users ab ON ab.id=COALESCE(t.assigned_by,t.created_by) LEFT JOIN users rv ON rv.id=t.reviewed_by WHERE t.id=?`).get(req.params.id);
  if(!taskAccessible(req,t))return res.status(t?403:404).json({error:t?'You cannot access this task.':'Task not found'});
  const history=db.prepare('SELECT h.*,u.name user_name FROM task_history h LEFT JOIN users u ON u.id=h.user_id WHERE h.task_id=? ORDER BY h.created_at DESC,h.id DESC').all(t.id);
  const comments=db.prepare('SELECT c.*,u.name user_name FROM task_comments c LEFT JOIN users u ON u.id=c.user_id WHERE c.task_id=? ORDER BY c.created_at,c.id').all(t.id);
  let attachments=[];try{attachments=JSON.parse(t.attachments_json||'[]')}catch(_){}
  res.json({task:{...t,attachments},history,comments});
});
app.put('/api/tasks/:id',auth,allow('tasks','performance'),(req,res)=>{
  const t=db.prepare('SELECT * FROM tasks WHERE id=?').get(req.params.id);
  if(!taskAccessible(req,t))return res.status(t?403:404).json({error:t?'You cannot update this task.':'Task not found'});
  const manager=isWorkManager(req.user),next={...t};
  if(manager){
    for(const k of ['title','priority','due_date','expected_result','description','complexity','related_module','related_entity_type'])if(req.body[k]!==undefined)next[k]=req.body[k];
    if(req.body.work_points!==undefined)next.work_points=Math.max(0,Number(req.body.work_points||0));
    if(req.body.related_entity_id!==undefined)next.related_entity_id=req.body.related_entity_id?Number(req.body.related_entity_id):null;
    if(req.body.review_required!==undefined){next.review_required=req.body.review_required?1:0;next.review_status=next.review_required?'Pending':'Not Required'}
    if(req.body.owner_id!==undefined){
      const owner=db.prepare('SELECT * FROM users WHERE id=? AND active=1').get(Number(req.body.owner_id));
      if(!owner||Number(owner.business_unit_id)!==Number(t.business_unit_id))return res.status(400).json({error:'Reassigned user must belong to the same business unit.'});
      next.owner_id=owner.id;
    }
  }
  if(req.body.status!==undefined){const status=String(req.body.status);if(!['Not Started','In Progress','Waiting','Completed','Cancelled'].includes(status))return res.status(400).json({error:'Invalid task status.'});next.status=status;}
  if(req.body.progress_percent!==undefined)next.progress_percent=Math.max(0,Math.min(100,Number(req.body.progress_percent||0)));
  if(next.status==='In Progress'&&!t.start_date)next.start_date=new Date().toISOString();
  if(next.status==='Completed'){next.progress_percent=100;next.completed_at=t.completed_at||new Date().toISOString();if(next.review_required)next.review_status='Pending'}
  if(next.status!=='Completed'&&t.status==='Completed'&&manager)next.completed_at=null;
  db.prepare(`UPDATE tasks SET title=?,owner_id=?,priority=?,status=?,due_date=?,expected_result=?,description=?,complexity=?,work_points=?,
    progress_percent=?,start_date=?,completed_at=?,related_module=?,related_entity_type=?,related_entity_id=?,review_required=?,review_status=?,
    assigned_by=COALESCE(assigned_by,created_by),updated_at=CURRENT_TIMESTAMP WHERE id=?`)
    .run(next.title,next.owner_id,next.priority,next.status,next.due_date,next.expected_result,next.description,next.complexity,next.work_points,
      next.progress_percent,next.start_date,next.completed_at,next.related_module,next.related_entity_type,next.related_entity_id,next.review_required,next.review_status,t.id);
  const action=next.owner_id!==t.owner_id?'Reassigned':'Progress Updated';
  db.prepare('INSERT INTO task_history(task_id,user_id,action,note) VALUES(?,?,?,?)').run(t.id,req.user.id,action,JSON.stringify(req.body));
  if(next.owner_id!==t.owner_id)notify(next.owner_id,'info','Work reassigned to you',next.title,t.business_unit_id,'task',t.id,'tasks');
  audit(req.user,'task',t.id,'update',JSON.stringify(req.body));res.json({ok:true});
});
app.post('/api/tasks/:id/comments',auth,allow('tasks','performance'),upload.single('attachment'),(req,res)=>{
  const t=db.prepare('SELECT * FROM tasks WHERE id=?').get(req.params.id);if(!taskAccessible(req,t))return res.status(t?403:404).json({error:t?'You cannot access this task.':'Task not found'});
  const comment=String(req.body.comment||'').trim();if(!comment)return res.status(400).json({error:'Comment/update is required.'});
  const r=db.prepare('INSERT INTO task_comments(task_id,user_id,comment,attachment_file) VALUES(?,?,?,?)').run(t.id,req.user.id,comment,req.file?'/uploads/'+req.file.filename:'');
  db.prepare('INSERT INTO task_history(task_id,user_id,action,note) VALUES(?,?,?,?)').run(t.id,req.user.id,'Comment',comment);
  const target=Number(req.user.id)===Number(t.owner_id)?(db.prepare('SELECT COALESCE(assigned_by,created_by) id FROM tasks WHERE id=?').get(t.id)?.id):t.owner_id;
  if(target)notify(target,'info','Task update',t.title+': '+comment.slice(0,120),t.business_unit_id,'task',t.id,'tasks');
  res.json({id:r.lastInsertRowid});
});
app.post('/api/tasks/:id/review',auth,allow('tasks','performance'),(req,res)=>{
  if(!isWorkManager(req.user))return res.status(403).json({error:'Only CEO or authorized managers can review work.'});
  const t=db.prepare('SELECT * FROM tasks WHERE id=?').get(req.params.id);if(!t)return res.status(404).json({error:'Task not found'});if(!enforceUnit(req,t.business_unit_id))return res.status(403).json({error:'You cannot review another business unit task.'});
  const decision=String(req.body.decision||'');if(!['Approved','Returned'].includes(decision))return res.status(400).json({error:'Decision must be Approved or Returned.'});
  if(decision==='Returned')db.prepare("UPDATE tasks SET review_status='Returned',status='In Progress',returned_count=COALESCE(returned_count,0)+1,completed_at=NULL,progress_percent=MIN(COALESCE(progress_percent,100),95),reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(req.user.id,t.id);
  else db.prepare("UPDATE tasks SET review_status='Approved',reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(req.user.id,t.id);
  const note=String(req.body.note||'').trim();db.prepare('INSERT INTO task_history(task_id,user_id,action,note) VALUES(?,?,?,?)').run(t.id,req.user.id,'Review '+decision,note);
  notify(t.owner_id,decision==='Approved'?'info':'warning','Task review '+decision,t.title+(note?' · '+note:''),t.business_unit_id,'task',t.id,'tasks');
  audit(req.user,'task',t.id,'review',JSON.stringify({decision,note}));res.json({ok:true});
});
app.delete('/api/tasks/:id',auth,allow('tasks','performance'),(req,res)=>{
  if(!isWorkManager(req.user))return res.status(403).json({error:'Only CEO or authorized managers can cancel assigned work.'});
  const t=db.prepare('SELECT * FROM tasks WHERE id=?').get(req.params.id);if(!t)return res.status(404).json({error:'Task not found'});if(!enforceUnit(req,t.business_unit_id))return res.status(403).json({error:'You cannot manage another business unit task.'});
  const reason=String(req.body?.reason||req.query.reason||'Cancelled by manager').trim();db.prepare("UPDATE tasks SET status='Cancelled',updated_at=CURRENT_TIMESTAMP WHERE id=?").run(t.id);
  db.prepare('INSERT INTO task_history(task_id,user_id,action,note) VALUES(?,?,?,?)').run(t.id,req.user.id,'Cancelled',reason);audit(req.user,'task',t.id,'cancel',reason);res.json({ok:true});
});

