function executeApprovedInventory(approval,decider){
  const snapshot=storedApprovalSnapshot(approval),body=snapshot.body||{},productId=Number(approval.source_id||snapshot.product_id||body.product_id||0),product=db.prepare('SELECT * FROM products WHERE id=?').get(productId),quantity=num(body.quantity),reason=String(body.reason||approval.reason||'Approved inventory write-off').trim();
  if(!product)throw new Error('Linked inventory product not found');if(quantity<=0)throw new Error('Approved inventory quantity must be greater than zero');if(countQuantityRequired(product.unit)&&!Number.isInteger(quantity))throw new Error('Quantity must be a whole number.');if(Number(product.current_stock||0)<quantity)throw new Error(`Insufficient stock: ${product.name}`);
  const actor=storedApprovalUser(approval),restaurant=String(approval.source_entity||'').startsWith('restaurant_waste');let result={};
  db.transaction(()=>{
    db.prepare('UPDATE products SET current_stock=current_stock-? WHERE id=?').run(quantity,product.id);
    if(restaurant){const waste=db.prepare('INSERT INTO restaurant_waste(business_unit_id,product_id,quantity,reason,estimated_cost,created_by) VALUES(?,?,?,?,?,?)').run(product.business_unit_id,product.id,quantity,reason,quantity*Number(product.cost_price||0),actor.id);const movement=db.prepare('INSERT INTO stock_movements(product_id,type,quantity,unit_cost,reason,reference_type,reference_id,user_id) VALUES(?,?,?,?,?,?,?,?)').run(product.id,'WASTE',quantity,product.cost_price,reason,'RESTAURANT_WASTE',waste.lastInsertRowid,actor.id);result={waste_id:Number(waste.lastInsertRowid),movement_id:Number(movement.lastInsertRowid)};db.prepare("UPDATE approvals SET source_entity='restaurant_waste',source_id=? WHERE id=?").run(result.waste_id,approval.id)}
    else{const movementType=String(body.type||'REMOVE').toUpperCase()==='WASTE'?'WASTE':'REMOVE',movement=db.prepare('INSERT INTO stock_movements(product_id,type,quantity,unit_cost,reason,user_id) VALUES(?,?,?,?,?,?)').run(product.id,movementType,quantity,product.cost_price,reason,actor.id);result={movement_id:Number(movement.lastInsertRowid)};db.prepare("UPDATE approvals SET source_entity='stock_movement',source_id=? WHERE id=?").run(result.movement_id,approval.id)}
  })();
  markApprovalExecuted(approval,decider,result);audit(actor,'inventory',product.id,'approved-writeoff',JSON.stringify({...result,quantity,reason,approval_id:approval.id}));return {executed:true,action:restaurant?'Inventory waste recorded':'Inventory adjustment recorded',...result};
}

app.post('/api/inventory/move',auth,allow('inventory'),(req,res)=>{
  const p=db.prepare('SELECT * FROM products WHERE id=?').get(req.body.product_id);
  if(p && !enforceUnit(req,p.business_unit_id))return res.status(403).json({error:'You cannot access another business unit inventory'});
  if(!p)return res.status(404).json({error:'Product not found'});
  let q=num(req.body.quantity);const type=String(req.body.type||'ADD').toUpperCase();
  if(q<=0)return res.status(400).json({error:'Quantity must be greater than zero'});if(countQuantityRequired(p.unit)&&!Number.isInteger(q))return res.status(400).json({error:'Quantity must be a whole number.'});
  if(!['ADD','REMOVE','WASTE','SALE'].includes(type))return res.status(400).json({error:'Invalid inventory movement type'});
  const isReduction=['REMOVE','WASTE','SALE'].includes(type),reason=String(req.body.reason||'').trim();
  if(isReduction && !reason)return res.status(400).json({error:'Reason is required for inventory removal/write-off.'});
  if(isReduction && Number(p.current_stock||0)<q)return res.status(400).json({error:'Insufficient stock'});
  let ap=null;
  // Direct SALE movements are generated by sale workflows; manual REMOVE/WASTE is an inventory adjustment/write-off.
  if(type==='REMOVE'||type==='WASTE'){
    const amount=q*Number(p.cost_price||0);
    ap=maybeCreateApproval({req,businessUnitId:p.business_unit_id,actionKey:'inventory.writeoff',type:'Inventory Adjustment / Write-off',amount,reason,sourceEntity:'inventory_adjustment',sourceId:p.id,priority:'High',snapshot:approvalRequestSnapshot(req,{business_unit_id:p.business_unit_id,product_id:p.id})});
    if(stopForApproval(res,ap,'Inventory adjustment submitted for approval.'))return;
  }
  const signed=isReduction?-q:q;
  db.prepare('UPDATE products SET current_stock=current_stock+? WHERE id=?').run(signed,p.id);
  const mv=db.prepare('INSERT INTO stock_movements(product_id,type,quantity,unit_cost,reason,user_id) VALUES(?,?,?,?,?,?)').run(p.id,type,q,p.cost_price,reason,req.user.id);
  if(ap?.approval)markApprovalExecuted(ap.approval,req.user);
  audit(req.user,'inventory',p.id,type,JSON.stringify({movement_id:mv.lastInsertRowid,quantity:q,reason}));
  res.json({ok:true,movement_id:mv.lastInsertRowid});
});
