function createSale(req,res,restaurant=false,skipApproval=false){
  const b=restaurant?db.prepare("SELECT id FROM business_units WHERE name='MIMI Resturant'").get()?.id:Number(req.body.business_unit_id);
  if(!b || !enforceUnit(req,b))return res.status(403).json({error:'Sale must belong to the current business unit'});
  const items=Array.isArray(req.body.items)?req.body.items:[];if(!items.length)return res.status(400).json({error:'Add at least one item'});
  let subtotal=0,cost=0,tax=0,clean=[];
  for(const it of items){
    const p=db.prepare('SELECT * FROM products WHERE id=? AND business_unit_id=?').get(it.product_id,b);if(!p)return res.status(400).json({error:'Invalid item'});
    const qty=num(it.quantity);if(qty<=0)return res.status(400).json({error:'Invalid quantity'});if(countQuantityRequired(p.unit)&&!Number.isInteger(qty))return res.status(400).json({error:'Quantity must be a whole number.'});
    if(p.item_type==='PRODUCT'&&Number(p.current_stock||0)<qty)return res.status(400).json({error:`Insufficient stock: ${p.name}`});
    const price=it.unit_price===undefined||it.unit_price===''?num(p.selling_price):num(it.unit_price),line=qty*price,tc=qty*num(p.cost_price),tt=line*(num(p.tax_rate)/100);
    subtotal+=line;cost+=tc;tax+=tt;clean.push({p,qty,price,line,tt});
  }
  const discount=num(req.body.discount),total=Math.max(0,subtotal-discount+tax),gp=total-cost;
  let ap=null;
  if(gp<0&&!skipApproval){
    const orderId=Number(req.approval_context?.restaurant_order_id||0)||null,sourceEntity=restaurant?'restaurant_sale_request':'sale_request';
    ap=maybeCreateApproval({req,businessUnitId:b,actionKey:'sale.loss_or_low_margin',type:'Loss / Below-Margin Sale',amount:Math.abs(gp),reason:`Proposed sale would record a gross loss of ${Math.abs(gp).toFixed(2)}.`,sourceEntity,sourceId:orderId,priority:'High',snapshot:approvalRequestSnapshot(req,{business_unit_id:b,restaurant,restaurant_order_id:orderId})});
    if(stopForApproval(res,ap,'Loss-making sale submitted for approval.'))return;
  }
  const invoice=nextNo(restaurant?'MIMI':'INV','sales','id');
  let saleId;
  const tx=db.transaction(()=>{
    const sale=db.prepare('INSERT INTO sales(business_unit_id,invoice_no,customer_id,customer_name,order_type,payment_method,subtotal,discount,tax,total,cost_total,gross_profit,receipt_file,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').run(b,invoice,req.body.customer_id||null,req.body.customer_name||'',req.body.order_type||'Sale',req.body.payment_method||'Cash',subtotal,discount,tax,total,cost,gp,req.body.receipt_file||'',req.body.notes||'',req.user.id);
    saleId=Number(sale.lastInsertRowid);
    const add=db.prepare('INSERT INTO sale_items(sale_id,product_id,item_type,item_name,quantity,unit_price,unit_cost,tax_rate,line_total) VALUES(?,?,?,?,?,?,?,?,?)');
    const move=db.prepare('INSERT INTO stock_movements(product_id,type,quantity,unit_cost,reason,reference_type,reference_id,user_id) VALUES(?,?,?,?,?,?,?,?)');
    for(const x of clean){
      add.run(saleId,x.p.id,x.p.item_type,x.p.name,x.qty,x.price,x.p.cost_price,x.p.tax_rate,x.line);
      if(x.p.item_type==='PRODUCT'){
        const changed=db.prepare('UPDATE products SET current_stock=current_stock-? WHERE id=? AND current_stock>=?').run(x.qty,x.p.id,x.qty);
        if(!changed.changes)throw new Error(`Insufficient stock: ${x.p.name}`);
        move.run(x.p.id,'SALE',x.qty,x.p.cost_price,invoice,'SALE',saleId,req.user.id);
      }
    }
    financeSync({businessUnitId:b,type:'Revenue',category:'Sales',amount:total,description:`${restaurant?'Restaurant POS':'Sale'} ${invoice}`,paymentMethod:req.body.payment_method||'Cash',reference:invoice,createdBy:req.user.id,sourceType:'Sale',sourceId:saleId,sourceLabel:restaurant?'MIMI POS → Sale':'Sales → Sale',sourceRecordId:saleId});
  });
  try{tx()}catch(e){return res.status(400).json({error:e.message||'Sale could not be completed'})}
  if(ap?.approval)markApprovalExecuted(ap.approval,req.user);
  audit(req.user,'sale',saleId,'create',JSON.stringify({invoice,total,gross_profit:gp}));
  res.json({id:saleId,invoice,total,gross_profit:gp});
}
function executeApprovedGeneralSale(approval,decider){
  const snapshot=storedApprovalSnapshot(approval),actor=storedApprovalUser(approval),restaurant=!!snapshot.restaurant,orderId=Number(snapshot.restaurant_order_id||approval.source_id||0)||null,request={body:snapshot.body||{},user:actor,selected_business_unit_id:approval.business_unit_id,headers:{'x-language':'ko'},approval_context:{restaurant_order_id:orderId}};
  const captured=captureInternalAction(response=>createSale(request,response,restaurant,true)),sale=captured.payload;if(!sale.id)throw new Error('Approved sale did not create a sale record');
  if(restaurant&&orderId){const order=db.prepare('SELECT * FROM restaurant_orders WHERE id=?').get(orderId);if(!order)throw new Error('Linked restaurant order not found');db.prepare("UPDATE restaurant_orders SET status='Closed',payment_method=?,subtotal=?,discount=?,tax=?,total=?,sale_id=?,closed_at=CURRENT_TIMESTAMP WHERE id=?").run(request.body.payment_method||'Cash',sale.total,num(request.body.discount),0,sale.total,sale.id,order.id);if(order.table_id)db.prepare("UPDATE restaurant_tables SET status='Available' WHERE id=?").run(order.table_id)}
  db.prepare("UPDATE approvals SET source_entity='sale',source_id=? WHERE id=?").run(sale.id,approval.id);markApprovalExecuted(approval,decider,{sale_id:sale.id,invoice:sale.invoice,restaurant_order_id:orderId});return {executed:true,action:'Sale completed',sale_id:sale.id,invoice:sale.invoice,restaurant_order_id:orderId};
}
