app.put('/api/sales/:id/void',auth,allow('sales','finance'),(req,res)=>{
  const s=db.prepare('SELECT * FROM sales WHERE id=?').get(req.params.id);
  if(s && !enforceUnit(req,s.business_unit_id))return res.status(403).json({error:'You cannot access another business unit sale'});
  if(!s)return res.status(404).json({error:'Sale not found'});
  if(s.status==='Voided')return res.json({ok:true,already_voided:true});
  const reason=String(req.body?.reason||'').trim();if(!reason)return res.status(400).json({error:'Void reason is required.'});
  const ap=maybeCreateApproval({req,businessUnitId:s.business_unit_id,actionKey:'payment.void',type:'Void Completed Sale',amount:s.total,reason,sourceEntity:'sale',sourceId:s.id,priority:'Critical'});
  if(stopForApproval(res,ap,'Sale void submitted for Finance + CEO approval. It will be applied automatically after final approval.'))return;
  const items=db.prepare('SELECT * FROM sale_items WHERE sale_id=?').all(s.id);
  const restore=db.prepare('UPDATE products SET current_stock=current_stock+? WHERE id=?');
  const move=db.prepare('INSERT INTO stock_movements(product_id,type,quantity,unit_cost,reason,reference_type,reference_id,user_id) VALUES(?,?,?,?,?,?,?,?)');
  const tx=db.transaction(()=>{
    db.prepare("UPDATE sales SET status='Voided',void_reason=?,voided_by=?,voided_at=CURRENT_TIMESTAMP WHERE id=?").run(reason,req.user.id,s.id);
    voidFinanceBySource('Sale',s.id,reason,req.user.id,s.business_unit_id);
    for(const it of items){
      if(String(it.item_type||'').toUpperCase()==='PRODUCT' && it.product_id){
        restore.run(Number(it.quantity||0),it.product_id);
        move.run(it.product_id,'SALE VOID',Number(it.quantity||0),Number(it.unit_cost||0),reason,'SALE_VOID',s.id,req.user.id);
      }
    }
  });
  tx();
  if(ap.approval)markApprovalExecuted(ap.approval,req.user);
  audit(req.user,'sale',s.id,'void',JSON.stringify({invoice:s.invoice_no,reason,stock_restored:true}));
  res.json({ok:true});
});


