function financeWarnings(f,source,attachments,linkedEvidence=[]){
  const warnings=[];
  const evidenceCount=Number(attachments?.length||0)+(f.receipt_file?1:0)+Number(linkedEvidence?.length||0);
  if(!evidenceCount)warnings.push({code:'missing_evidence',level:'warning',message:'No receipt or supporting evidence is attached.'});
  if(!String(f.reference||'').trim())warnings.push({code:'missing_reference',level:'warning',message:'Payment/reference number is missing.'});
  if(String(f.original_currency||'KRW').toUpperCase()!=='KRW' && Number(f.fx_rate||0)<=0)warnings.push({code:'missing_fx',level:'critical',message:'Foreign-currency transaction has no valid historical FX rate.'});
  if(source?.amount!=null && Math.abs(Number(source.amount||0)-Number(f.krw_amount||f.amount||0))>0.01)warnings.push({code:'amount_mismatch',level:'critical',message:`Finance amount does not match the linked source amount (source ₩${Number(source.amount||0).toLocaleString()}).`});
  if(source?.reference && f.reference && String(source.reference)!==String(f.reference))warnings.push({code:'reference_mismatch',level:'warning',message:'Finance reference differs from the linked source reference.'});
  if(f.source_type&&f.source_id!=null){const dup=db.prepare("SELECT COUNT(*) c FROM finance_entries WHERE business_unit_id=? AND source_type=? AND source_id=? AND status!='Voided'").get(f.business_unit_id,f.source_type,f.source_id)?.c||0;if(dup>1)warnings.push({code:'duplicate_source',level:'critical',message:`${dup} active Finance records point to the same source transaction.`})}
  if(f.verified_at&&f.updated_at&&String(f.updated_at)>String(f.verified_at))warnings.push({code:'changed_after_verification',level:'critical',message:'The linked Finance record changed after it was verified and requires re-verification.'});
  return warnings;
}
function financeTimeline(f){
  const rows=db.prepare("SELECT action,details,created_at FROM audit_log WHERE entity='finance' AND entity_id=? ORDER BY id").all(f.id);
  const timeline=[{action:'Finance entry created / synchronized',details:`${f.source_type||'Manual'}${f.source_id?' #'+f.source_id:''}`,created_at:f.created_at}];
  for(const r of rows)timeline.push(r);
  if(f.verified_at)timeline.push({action:f.verification_status==='Rejected / Incorrect'?'Correction requested':'Finance reviewed',details:f.verification_note||f.verification_status,created_at:f.verified_at});
  if(f.voided_at)timeline.push({action:'Voided',details:f.void_reason||'',created_at:f.voided_at});
  return timeline.sort((a,b)=>String(a.created_at||'').localeCompare(String(b.created_at||'')));
}
