function openFinanceCorrection({finance,requestedBy,reason,severity='Normal',requestedChanges=''}){
  const assignedTo=Number(finance.created_by||requestedBy);
  if(!assignedTo)throw new Error('The Finance record has no original creator to receive this correction');
  const snapshot=financeCorrectionSnapshot(finance),priority=severity==='Critical'?'Critical':severity==='High'?'High':'Normal';
  const transaction=db.transaction(()=>{
    let correction=db.prepare("SELECT * FROM finance_correction_requests WHERE finance_entry_id=? AND status IN ('Open','Viewed','Resubmitted') ORDER BY id DESC LIMIT 1").get(finance.id);
    if(correction){
      db.prepare("UPDATE finance_correction_requests SET reason=?,requested_changes=?,severity=?,status='Open',requested_by=?,assigned_to=?,requested_at=CURRENT_TIMESTAMP,due_at=datetime('now','+3 days'),source_snapshot_json=CASE WHEN COALESCE(source_snapshot_json,'{}')='{}' THEN ? ELSE source_snapshot_json END,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(reason,requestedChanges||reason,severity,requestedBy,assignedTo,JSON.stringify(snapshot),correction.id);
      correction=db.prepare('SELECT * FROM finance_correction_requests WHERE id=?').get(correction.id);
      if(correction.task_id)db.prepare("UPDATE tasks SET owner_id=?,business_unit_id=?,priority=?,status='In Progress',due_date=date('now','+3 days'),description=?,expected_result=?,progress_percent=0,review_required=1,review_status='Pending',returned_count=COALESCE(returned_count,0)+1,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(assignedTo,finance.business_unit_id,priority,requestedChanges||reason,'Correct the linked source transaction and resubmit it for Finance verification.',correction.task_id);
    }else{
      const cr=db.prepare("INSERT INTO finance_correction_requests(finance_entry_id,business_unit_id,assigned_to,requested_by,reason,requested_changes,severity,status,due_at,source_snapshot_json) VALUES(?,?,?,?,?,?,?,'Open',datetime('now','+3 days'),?)").run(finance.id,finance.business_unit_id,assignedTo,requestedBy,reason,requestedChanges||reason,severity,JSON.stringify(snapshot));
      correction=db.prepare('SELECT * FROM finance_correction_requests WHERE id=?').get(cr.lastInsertRowid);
    }
    if(!correction.task_id){
      const task=db.prepare(`INSERT INTO tasks(title,owner_id,business_unit_id,priority,status,due_date,expected_result,created_by,description,complexity,work_points,progress_percent,related_module,related_entity_type,related_entity_id,review_required,review_status,assigned_by,updated_at)
        VALUES(?,?,?,?,?,date('now','+3 days'),?,?,?,?,?,?,?,?,?,?,?, ?,CURRENT_TIMESTAMP)`).run(`Finance correction required — #${finance.id}`,assignedTo,finance.business_unit_id,priority,'Not Started','Correct the linked source transaction and resubmit it for Finance verification.',requestedBy,requestedChanges||reason,'Medium',3,0,'Finance','finance_correction',correction.id,1,'Pending',requestedBy);
      db.prepare('UPDATE finance_correction_requests SET task_id=? WHERE id=?').run(task.lastInsertRowid,correction.id);correction=db.prepare('SELECT * FROM finance_correction_requests WHERE id=?').get(correction.id);
      db.prepare('INSERT INTO task_history(task_id,user_id,action,note) VALUES(?,?,?,?)').run(task.lastInsertRowid,requestedBy,'Assigned',reason);
    }
    financeCorrectionHistory(correction,requestedBy,correction.resubmission_count?'Correction Requested Again':'Correction Requested',reason,{requested_changes:requestedChanges||reason,severity,snapshot});
    notify(assignedTo,severity==='Critical'?'critical':'warning','Finance correction required',`Finance #${finance.id}: ${requestedChanges||reason}`,finance.business_unit_id,'finance_correction',correction.id,'financeCorrection',correction.id);
    return correction.id;
  });
  return Number(transaction());
}
function normalizeLegacyFinanceRejections(){try{const rows=db.prepare("SELECT * FROM finance_entries WHERE verification_status IN ('Rejected','Rejected / Incorrect')").all();for(const finance of rows){const reason=finance.correction_reason||finance.verification_note||'Legacy rejected record requires correction';db.prepare("UPDATE finance_entries SET verification_status='Correction Required',correction_reason=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(reason,finance.id);if(finance.created_by)openFinanceCorrection({finance:{...finance,verification_status:'Correction Required'},requestedBy:finance.verified_by||finance.created_by,reason,requestedChanges:reason,severity:'High'})}}catch(error){console.error('V28.2 legacy Finance correction migration:',error.message)}}
normalizeLegacyFinanceRejections();
