function reportAccessible(req,r){if(!r)return false;if(!enforceUnit(req,r.business_unit_id))return false;return isWorkManager(req.user)||Number(r.user_id)===Number(req.user.id)}
function reportRecipients(businessUnitId,mode){
  const ids=new Set();
  if(mode==='Manager'||mode==='Manager + CEO'||mode==='Both')db.prepare("SELECT id FROM users WHERE active=1 AND business_unit_id=? AND role IN ('Operations Manager','Business Unit Manager')").all(businessUnitId).forEach(x=>ids.add(x.id));
  if(mode==='CEO'||mode==='Manager + CEO'||mode==='Both')db.prepare("SELECT id FROM users WHERE active=1 AND role='CEO / Owner'").all().forEach(x=>ids.add(x.id));
  return [...ids];
}
