app.post('/api/restaurant/orders',auth,allow('restaurant','pos'),(req,res)=>{const b=db.prepare("SELECT id FROM business_units WHERE name='MIMI Resturant'").get()?.id;if(!b)return res.status(404).json({error:'MIMI Resturant not found'});if(!enforceUnit(req,b))return res.status(403).json({error:'Select MIMI Resturant to use restaurant functions'});const items=Array.isArray(req.body.items)?req.body.items:[];if(!items.length)return res.status(400).json({error:'Add items'});const orderNo=nextNo('MIMI','restaurant_orders','id');const tableId=req.body.table_id||null;if((req.body.order_type||'Dine-in')==='Dine-in'&&!tableId)return res.status(400).json({error:'Select an available table for dine-in'});if((req.body.order_type||'Dine-in')==='Dine-in'&&tableId){const t=db.prepare('SELECT * FROM restaurant_tables WHERE id=? AND business_unit_id=?').get(tableId,b);if(!t)return res.status(400).json({error:'Invalid table'});if(t.status!=='Available')return res.status(400).json({error:'Selected table is not available'});}const r=db.prepare('INSERT INTO restaurant_orders(business_unit_id,table_id,order_no,order_type,customer_name,status,created_by) VALUES(?,?,?,?,?,?,?)').run(b,tableId,orderNo,req.body.order_type||'Dine-in',req.body.customer_name||'','Open',req.user.id);if(tableId)db.prepare("UPDATE restaurant_tables SET status='Busy' WHERE id=?").run(tableId);const add=db.prepare('INSERT INTO restaurant_order_items(order_id,product_id,item_name,quantity,unit_price,unit_cost,line_total,kitchen_status,notes) VALUES(?,?,?,?,?,?,?,?,?)');for(const it of items){const p=db.prepare('SELECT * FROM products WHERE id=? AND business_unit_id=?').get(it.product_id,b);if(!p)return res.status(400).json({error:'Invalid menu item'});const q=num(it.quantity);const price=it.unit_price===undefined?p.selling_price:num(it.unit_price);if(price<0)return res.status(400).json({error:'Invalid price'});add.run(r.lastInsertRowid,p.id,p.name,q,price,p.cost_price,q*price,'Pending',it.notes||'');}res.json({id:r.lastInsertRowid,order_no:orderNo});});
app.post('/api/restaurant/orders/:id/cancel',auth,allow('restaurant','pos'),(req,res)=>{const o=db.prepare('SELECT * FROM restaurant_orders WHERE id=?').get(req.params.id);if(!o)return res.status(404).json({error:'Order not found'});if(!enforceUnit(req,o.business_unit_id))return res.status(403).json({error:'Wrong business unit'});if(o.status!=='Open')return res.status(400).json({error:'Only open orders can be cancelled'});const reason=(req.body?.reason||'Cancelled by user').trim();db.prepare("UPDATE restaurant_orders SET status='Cancelled',closed_at=CURRENT_TIMESTAMP WHERE id=?").run(o.id);if(o.table_id)db.prepare("UPDATE restaurant_tables SET status='Available' WHERE id=? AND business_unit_id=?").run(o.table_id,o.business_unit_id);audit(req.user,'restaurant_order',o.id,'cancel',JSON.stringify({order_no:o.order_no,reason}));res.json({ok:true,status:'Cancelled',order_no:o.order_no});});
app.delete('/api/restaurant/orders/:id',auth,allow('restaurant','pos'),(req,res)=>{const o=db.prepare('SELECT * FROM restaurant_orders WHERE id=?').get(req.params.id);if(!o)return res.status(404).json({error:'Order not found'});if(!enforceUnit(req,o.business_unit_id))return res.status(403).json({error:'Wrong business unit'});if(o.status!=='Open')return res.status(400).json({error:'Only open orders can be deleted'});const reason=(req.body?.reason||'Deleted/cancelled by user').trim();db.prepare("UPDATE restaurant_orders SET status='Cancelled',closed_at=CURRENT_TIMESTAMP WHERE id=?").run(o.id);if(o.table_id)db.prepare("UPDATE restaurant_tables SET status='Available' WHERE id=? AND business_unit_id=?").run(o.table_id,o.business_unit_id);audit(req.user,'restaurant_order',o.id,'delete',JSON.stringify({order_no:o.order_no,reason}));res.json({ok:true,status:'Cancelled',order_no:o.order_no});});
