app.post('/api/restaurant/orders/:id/save',auth,allow('restaurant','pos'),(req,res)=>{const o=db.prepare('SELECT * FROM restaurant_orders WHERE id=?').get(req.params.id);if(!o)return res.status(404).json({error:'Order not found'});if(!enforceUnit(req,o.business_unit_id))return res.status(403).json({error:'Wrong business unit'});if(o.status!=='Open')return res.status(400).json({error:'Only open orders can be saved'});const items=db.prepare('SELECT * FROM restaurant_order_items WHERE order_id=?').all(o.id);const subtotal=items.reduce((a,x)=>a+num(x.line_total),0);db.prepare('UPDATE restaurant_orders SET subtotal=?,total=? WHERE id=?').run(subtotal,subtotal,o.id);audit(req.user,'restaurant_order',o.id,'save');res.json({ok:true,subtotal,total:subtotal});});
app.post('/api/restaurant/orders/:id/close',auth,allow('restaurant','pos'),(req,res)=>{
  const o=db.prepare('SELECT * FROM restaurant_orders WHERE id=?').get(req.params.id);
  if(o && !enforceUnit(req,o.business_unit_id))return res.status(403).json({error:'You cannot access another business unit restaurant order'});
  if(!o)return res.status(404).json({error:'Order not found'});if(o.status!=='Open')return res.status(400).json({error:'Only open orders can be closed.'});
  const items=db.prepare('SELECT * FROM restaurant_order_items WHERE order_id=?').all(o.id);
  const saleReq={body:{business_unit_id:o.business_unit_id,customer_name:o.customer_name,order_type:o.order_type,payment_method:req.body.payment_method||'Cash',items:items.map(x=>({product_id:x.product_id,quantity:x.quantity,unit_price:x.unit_price})),discount:req.body.discount||0},user:req.user,selected_business_unit_id:req.selected_business_unit_id,headers:req.headers,approval_context:{restaurant_order_id:o.id}};
  let statusCode=200;const proxy={status(code){statusCode=code;return proxy},json(x){
    if(statusCode>=400||x.error)return res.status(statusCode>=400?statusCode:400).json(x);
    if(statusCode===202||x.approval_required)return res.status(202).json(x);
    db.prepare("UPDATE restaurant_orders SET status='Closed',payment_method=?,subtotal=?,discount=?,tax=?,total=?,sale_id=?,closed_at=CURRENT_TIMESTAMP WHERE id=?").run(req.body.payment_method||'Cash',x.total,num(req.body.discount),0,x.total,x.id,o.id);
    const t=db.prepare('SELECT table_id FROM restaurant_orders WHERE id=?').get(o.id);if(t.table_id)db.prepare("UPDATE restaurant_tables SET status='Available' WHERE id=?").run(t.table_id);
    res.json(x);
  }};
  createSale(saleReq,proxy,true);
});
app.post('/api/restaurant/waste',auth,allow('restaurant','inventory'),(req,res)=>{
  const p=db.prepare('SELECT * FROM products WHERE id=?').get(req.body.product_id);if(p&&!enforceUnit(req,p.business_unit_id))return res.status(403).json({error:'You cannot access another business unit inventory'});if(!p)return res.status(404).json({error:'Product not found'});
  const q=num(req.body.quantity);if(q<=0)return res.status(400).json({error:'Waste quantity must be greater than zero.'});if(p.current_stock<q)return res.status(400).json({error:'Insufficient stock'});const amount=q*Number(p.cost_price||0),reason=String(req.body.reason||'').trim()||'Inventory waste/write-off';
  const ap=maybeCreateApproval({req,businessUnitId:p.business_unit_id,actionKey:'inventory.writeoff',type:'Inventory Waste / Write-off',amount,reason,sourceEntity:'restaurant_waste_request',sourceId:p.id,priority:'High',snapshot:approvalRequestSnapshot(req,{business_unit_id:p.business_unit_id,product_id:p.id})});
  if(stopForApproval(res,ap,`Inventory write-off submitted for ${approvalLevelName(ap.approval?.required_level||2)} approval.`))return;
  db.prepare('UPDATE products SET current_stock=current_stock-? WHERE id=?').run(q,p.id);const r=db.prepare('INSERT INTO restaurant_waste(business_unit_id,product_id,quantity,reason,estimated_cost,created_by) VALUES(?,?,?,?,?,?)').run(p.business_unit_id,p.id,q,reason,amount,req.user.id);db.prepare('INSERT INTO stock_movements(product_id,type,quantity,unit_cost,reason,user_id) VALUES(?,?,?,?,?,?)').run(p.id,'WASTE',q,p.cost_price,reason,req.user.id);if(ap.approval)markApprovalExecuted(ap.approval,req.user);audit(req.user,'inventory_waste',r.lastInsertRowid,'create',JSON.stringify({product_id:p.id,quantity:q,amount,reason}));res.json({id:r.lastInsertRowid});
});
app.post('/api/restaurant/closing',auth,allow('restaurant','finance'),(req,res)=>{const b=db.prepare("SELECT id FROM business_units WHERE name='MIMI Resturant'").get()?.id;if(!b||!enforceUnit(req,b))return res.status(403).json({error:'Select MIMI Resturant to use restaurant functions'});const d=req.body.business_date||new Date().toISOString().slice(0,10);const sales=db.prepare(`SELECT COALESCE(SUM(CASE WHEN payment_method='Cash' THEN total ELSE 0 END),0)cash,COALESCE(SUM(CASE WHEN payment_method IN ('Card','Bank') THEN total ELSE 0 END),0)card,COALESCE(SUM(CASE WHEN payment_method NOT IN ('Cash','Card','Bank') THEN total ELSE 0 END),0)other FROM sales WHERE business_unit_id=? AND date(created_at)=?`).get(b,d);const variance=num(req.body.cash_counted)-sales.cash;const r=db.prepare(`INSERT INTO restaurant_closings(business_unit_id,business_date,cash_sales,card_sales,other_sales,cash_counted,variance,notes,closed_by) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(business_unit_id,business_date) DO UPDATE SET cash_sales=excluded.cash_sales,card_sales=excluded.card_sales,other_sales=excluded.other_sales,cash_counted=excluded.cash_counted,variance=excluded.variance,notes=excluded.notes,closed_by=excluded.closed_by`).run(b,d,sales.cash,sales.card,sales.other,num(req.body.cash_counted),variance,req.body.notes||'',req.user.id);res.json({id:r.lastInsertRowid,...sales,variance});});


// MIMI Restaurant upgraded modules: menu, stock, weekly menu, buffet, open-order editing and table-aware dine-in.
function mimiId(){return db.prepare("SELECT id FROM business_units WHERE name='MIMI Resturant'").get()?.id;}
function mimiGuard(req,res){const b=mimiId();if(!b)return null;if(!enforceUnit(req,b)){res.status(403).json({error:'Select MIMI Resturant to use restaurant functions'});return null;}return b;}
function syncBuffetProduct(buffet){const sku=`MIMI-BUFFET-${buffet.id}`;let p=db.prepare('SELECT * FROM products WHERE business_unit_id=? AND sku=?').get(buffet.business_unit_id,sku);const active=buffet.status==='Published';if(!p){const r=db.prepare('INSERT INTO products(business_unit_id,sku,name,category,supplier,item_type,unit,opening_stock,current_stock,reorder_level,cost_price,selling_price,tax_rate,active) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)').run(buffet.business_unit_id,sku,`Buffet: ${buffet.name}`,'Buffet','MIMI','SERVICE','buffet',0,0,0,0,num(buffet.price),0,active?1:0);p=db.prepare('SELECT * FROM products WHERE id=?').get(r.lastInsertRowid);}else{db.prepare('UPDATE products SET name=?,selling_price=?,active=? WHERE id=?').run(`Buffet: ${buffet.name}`,num(buffet.price),active?1:0,p.id);p=db.prepare('SELECT * FROM products WHERE id=?').get(p.id);}return p;}
app.get('/api/restaurant/dashboard',auth,allow('restaurant','pos'),(req,res)=>{const b=mimiGuard(req,res);if(!b)return;const sales=db.prepare("SELECT COALESCE(SUM(total),0) total,COALESCE(SUM(gross_profit),0) profit,COUNT(*) count FROM sales WHERE business_unit_id=? AND date(created_at)=date('now') AND status<>'Voided'").get(b);const stock=db.prepare("SELECT COALESCE(SUM(current_stock*cost_price),0) value,COUNT(*) low FROM products WHERE business_unit_id=? AND active=1 AND item_type='PRODUCT' AND current_stock<=reorder_level AND reorder_level>0").get(b);const open=db.prepare("SELECT COUNT(*) count FROM restaurant_orders WHERE business_unit_id=? AND status='Open'").get(b);const tables=db.prepare("SELECT status,COUNT(*) count FROM restaurant_tables WHERE business_unit_id=? GROUP BY status").all(b);res.json({sales,stock,open,tables});});
app.get('/api/restaurant/menu/:id/recipe',auth,allow('restaurant','pos'),(req,res)=>{const b=mimiGuard(req,res);if(!b)return;const m=db.prepare('SELECT * FROM restaurant_menu_items WHERE id=? AND business_unit_id=?').get(req.params.id,b);if(!m)return res.status(404).json({error:'Menu item not found'});res.json(db.prepare('SELECT r.*,p.name product_name,p.unit product_unit,p.current_stock,p.cost_price FROM restaurant_recipes r JOIN products p ON p.id=r.product_id WHERE r.menu_item_id=? ORDER BY p.name').all(m.id));});
app.post('/api/restaurant/menu/:id/recipe',auth,allow('restaurant'),(req,res)=>{const b=mimiGuard(req,res);if(!b)return;const m=db.prepare('SELECT * FROM restaurant_menu_items WHERE id=? AND business_unit_id=?').get(req.params.id,b);const p=db.prepare("SELECT * FROM products WHERE id=? AND business_unit_id=? AND item_type='PRODUCT'").get(req.body.product_id,b);const q=num(req.body.quantity);if(!m||!p)return res.status(400).json({error:'Invalid menu item or ingredient'});if(q<=0)return res.status(400).json({error:'Quantity must be positive'});db.prepare('INSERT INTO restaurant_recipes(menu_item_id,product_id,quantity,unit) VALUES(?,?,?,?) ON CONFLICT(menu_item_id,product_id) DO UPDATE SET quantity=excluded.quantity,unit=excluded.unit').run(m.id,p.id,q,req.body.unit||p.unit);audit(req.user,'restaurant_recipe',m.id,'upsert',JSON.stringify({product_id:p.id,quantity:q}));res.json({ok:true});});
