app.post('/api/restaurant/menu/:id/stock',auth,allow('restaurant','inventory'),(req,res)=>{const b=mimiGuard(req,res);if(!b)return;const m=db.prepare('SELECT * FROM restaurant_menu_items WHERE id=? AND business_unit_id=?').get(req.params.id,b);if(!m)return res.status(404).json({error:'Menu item not found'});const p=db.prepare('SELECT * FROM products WHERE id=? AND business_unit_id=? AND item_type=\'PRODUCT\'').get(m.product_id,b);if(!p)return res.status(404).json({error:'Menu item product not found'});const q=num(req.body.quantity);if(q<=0)return res.status(400).json({error:'Quantity must be positive'});const type=req.body.type||'RECEIVE';const delta=type==='ISSUE'||type==='WASTE'||type==='SALE'?-q:q;if(p.current_stock+delta<0)return res.status(400).json({error:'Insufficient stock'});db.prepare('UPDATE products SET current_stock=current_stock+? WHERE id=?').run(delta,p.id);db.prepare('INSERT INTO stock_movements(product_id,type,quantity,unit_cost,reason,user_id) VALUES(?,?,?,?,?,?)').run(p.id,type,q,p.cost_price,req.body.reason||'Menu item stock update',req.user.id);audit(req.user,'restaurant_menu_stock',m.id,'update',JSON.stringify({product_id:p.id,type,quantity:q,reason:req.body.reason||''}));res.json({ok:true,menu_item_id:m.id,current_stock:p.current_stock+delta});});
