app.put('/api/restaurant/menu/:id',auth,allow('restaurant'),(req,res)=>{const b=mimiGuard(req,res);if(!b)return;const m=db.prepare('SELECT * FROM restaurant_menu_items WHERE id=? AND business_unit_id=?').get(req.params.id,b);if(!m)return res.status(404).json({error:'Menu item not found'});db.prepare('UPDATE restaurant_menu_items SET name=?,category=?,price=?,active=?,available=?,description=?,price_mode=?,tax_rate=? WHERE id=?').run(req.body.name??m.name,req.body.category??m.category,num(req.body.price??m.price),req.body.active===undefined?m.active:num(req.body.active),req.body.available===undefined?m.available:num(req.body.available),req.body.description??m.description,req.body.price_mode??m.price_mode,num(req.body.tax_rate??m.tax_rate),m.id);res.json({ok:true});});
