function excavatorCostSnapshot(assetId){
  const a=db.prepare('SELECT * FROM excavator_assets WHERE id=?').get(assetId);if(!a)return null;
  const tx=db.prepare("SELECT * FROM excavator_transactions WHERE asset_id=? AND status!='Cancelled'").all(assetId),parse=t=>{try{return t.metadata?JSON.parse(t.metadata):{}}catch(_){return{}}},included=t=>parse(t).include_in_machine_cost!==false,sum=rows=>rows.reduce((n,x)=>n+Number(x.amount||0),0),linked=(type,key,id)=>tx.some(t=>t.type===type&&Number(parse(t)[key]||0)===Number(id));
  const purchaseTx=sum(tx.filter(t=>t.type==='Purchase'&&included(t))),purchase=purchaseTx||Number(a.purchase_price||0);
  const logistics=sum(tx.filter(t=>t.type==='Logistics'&&included(t)))+db.prepare('SELECT * FROM excavator_logistics WHERE asset_id=?').all(assetId).filter(x=>!linked('Logistics','logistics_id',x.id)).reduce((n,x)=>n+Number(x.amount||0),0);
  const repair=sum(tx.filter(t=>t.type==='Repair'&&included(t)))+db.prepare('SELECT * FROM excavator_repairs WHERE asset_id=?').all(assetId).filter(x=>!linked('Repair','repair_id',x.id)).reduce((n,x)=>n+Number(x.amount||0),0);
  const partCost=sum(tx.filter(t=>t.type==='Part Purchase'&&included(t)))+db.prepare('SELECT * FROM excavator_parts WHERE asset_id=?').all(assetId).filter(x=>!['Sold','Exported'].includes(x.status)&&!linked('Part Purchase','part_id',x.id)).reduce((n,x)=>n+Number(x.cost||0)*Number(x.quantity||1),0);
  const other=sum(tx.filter(t=>['Customs Duty','Tax / VAT','Shipping / Freight','Commission','Documentation / Clearance','Other Cost'].includes(t.type)&&included(t)));
  return {purchase,logistics,repair,partCost,other,total:purchase+logistics+repair+partCost+other};
}
function buyerAdvanceAvailableForAsset(buyerId,assetId){
  const paid=Number(db.prepare("SELECT COALESCE(SUM(krw_amount),0) v FROM excavator_buyer_payments WHERE buyer_id=? AND COALESCE(status,'Active')!='Voided'").get(buyerId).v||0);
  const allocated=Number(db.prepare("SELECT COALESCE(SUM(al.amount_krw),0) v FROM excavator_buyer_payment_allocations al JOIN excavator_buyer_payments p ON p.id=al.payment_id WHERE al.buyer_id=? AND COALESCE(al.status,'Active')='Active' AND COALESCE(p.status,'Active')!='Voided' AND (al.asset_id IS NULL OR al.asset_id!=?)").get(buyerId,assetId).v||0);
  const legacy=Number(db.prepare("SELECT COALESCE(SUM(p.krw_amount),0) v FROM excavator_buyer_payments p WHERE p.buyer_id=? AND COALESCE(p.status,'Active')!='Voided' AND p.asset_id IS NOT NULL AND p.asset_id!=? AND NOT EXISTS (SELECT 1 FROM excavator_buyer_payment_allocations al WHERE al.payment_id=p.id AND COALESCE(al.status,'Active')='Active')").get(buyerId,assetId).v||0);
  const refunded=Number(db.prepare("SELECT COALESCE(SUM(krw_amount),0) v FROM excavator_buyer_refunds WHERE buyer_id=? AND status='Completed'").get(buyerId).v||0);
  return Math.max(0,paid-allocated-legacy-refunded);
}
// V28.6: generic advance pool intentionally excludes payments created specifically by
// a completed machine sale. Those sale-specific payments cannot silently become reusable advance.
function buyerGenericAdvanceAvailableForAsset(buyerId,assetId){
  const sourceFilter="COALESCE(p.source_type,'')!='Excavator Sale' AND COALESCE(p.notes,'') NOT LIKE 'Created from %machine sale%'";
  const paid=Number(db.prepare(`SELECT COALESCE(SUM(p.krw_amount),0) v FROM excavator_buyer_payments p WHERE p.buyer_id=? AND COALESCE(p.status,'Active')!='Voided' AND ${sourceFilter}`).get(buyerId).v||0);
  const allocated=Number(db.prepare(`SELECT COALESCE(SUM(al.amount_krw),0) v FROM excavator_buyer_payment_allocations al JOIN excavator_buyer_payments p ON p.id=al.payment_id WHERE al.buyer_id=? AND COALESCE(al.status,'Active')='Active' AND COALESCE(p.status,'Active')!='Voided' AND ${sourceFilter} AND (al.asset_id IS NULL OR al.asset_id!=?)`).get(buyerId,assetId).v||0);
  const legacy=Number(db.prepare(`SELECT COALESCE(SUM(p.krw_amount),0) v FROM excavator_buyer_payments p WHERE p.buyer_id=? AND COALESCE(p.status,'Active')!='Voided' AND ${sourceFilter} AND p.asset_id IS NOT NULL AND p.asset_id!=? AND NOT EXISTS (SELECT 1 FROM excavator_buyer_payment_allocations al WHERE al.payment_id=p.id AND COALESCE(al.status,'Active')='Active')`).get(buyerId,assetId).v||0);
  const refunded=Number(db.prepare("SELECT COALESCE(SUM(krw_amount),0) v FROM excavator_buyer_refunds WHERE buyer_id=? AND status='Completed'").get(buyerId).v||0);
  return Math.max(0,paid-allocated-legacy-refunded);
}
