  const buyer=buyerId?db.prepare('SELECT * FROM excavator_buyers WHERE id=? AND business_unit_id=?').get(buyerId,businessUnitId):null;
  const supplier=a.supplier_id?db.prepare('SELECT * FROM excavator_suppliers WHERE id=? AND business_unit_id=?').get(a.supplier_id,businessUnitId):null;
  const transactions=db.prepare("SELECT * FROM excavator_transactions WHERE asset_id=? AND status!='Cancelled' ORDER BY transaction_date ASC,id ASC").all(a.id);
  const costTypes=['Purchase','Logistics','Repair','Part Purchase','Customs Duty','Tax / VAT','Shipping / Freight','Commission','Documentation / Clearance','Other Cost'];
  const includedCost=x=>{if(!x.metadata)return true;try{return JSON.parse(x.metadata).include_in_machine_cost!==false}catch(_){return true}};
  const costs=transactions.filter(x=>costTypes.includes(x.type)&&includedCost(x));
  const totalCost=Number(excavatorCostSnapshot(a.id)?.total||0);
  const purchasePayments=db.prepare("SELECT * FROM excavator_payments WHERE asset_id=? AND payment_type='Purchase' ORDER BY paid_date,due_date,id").all(a.id);
  const salePayments=db.prepare("SELECT * FROM excavator_payments WHERE asset_id=? AND payment_type='Sale' ORDER BY paid_date,due_date,id").all(a.id);
  const allocations=db.prepare(`SELECT al.*,p.payment_date,p.reference,p.currency,p.original_amount FROM excavator_buyer_payment_allocations al
    JOIN excavator_buyer_payments p ON p.id=al.payment_id
    WHERE al.asset_id=? AND COALESCE(al.status,'Active')='Active' AND COALESCE(p.status,'Active')!='Voided' ORDER BY al.id`).all(a.id);
  const parts=db.prepare('SELECT * FROM excavator_parts WHERE asset_id=? ORDER BY purchase_date,id').all(a.id);
  const repairs=db.prepare('SELECT * FROM excavator_repairs WHERE asset_id=? ORDER BY repair_date,id').all(a.id);
  const logistics=db.prepare('SELECT * FROM excavator_logistics WHERE asset_id=? ORDER BY logistics_date,id').all(a.id);
  const documents=db.prepare('SELECT * FROM excavator_documents WHERE asset_id=? ORDER BY created_at,id').all(a.id);
  const history=db.prepare('SELECT e.*,u.name user_name FROM excavator_lifecycle_events e LEFT JOIN users u ON u.id=e.user_id WHERE e.asset_id=? ORDER BY e.created_at,id').all(a.id);
  const paidPurchase=Number(db.prepare("SELECT COALESCE(SUM(amount),0) total FROM excavator_payments WHERE asset_id=? AND payment_type='Purchase' AND status='Paid'").get(a.id).total||0);
  const amount=Number(sale.amount||0),saleType=sale.type,saleDate=sale.transaction_date||'',customer=meta.customer_name||sale.counterparty||buyer?.name||'';
  const lang=language==='en'?'en':'ko';
  const report={language:lang,asset:{...a,purchase_paid:paidPurchase},machineDisplay:[a.machine_name,a.make,a.model].filter(Boolean).join(' ')||a.asset_no,supplier,buyer,customer,
    destination:meta.destination_country||'',shipping:meta.shipping_reference||'',saleType,saleDate,amount,saleAmount:amount,
    paymentDate:meta.payment_date||'',paymentReference:meta.payment_reference||'',paymentMethod:meta.payment_method||'',
    notes:String(sale.notes||''),sellNote:meta.sell_note||'',totalCost,profit:amount-totalCost,costs,purchasePayments,salePayments,allocations,parts,repairs,logistics,documents,history,salePaid:amount,
    money:n=>Number(n||0).toLocaleString(lang==='ko'?'ko-KR':'en-US',{minimumFractionDigits:2,maximumFractionDigits:2})};
  const pdf=salePdfBuffer(report),filename=`excavator-sale-${a.asset_no.replace(/[^a-z0-9_-]/gi,'_')}-${Date.now()}.pdf`;
  fs.writeFileSync(path.join(uploads,filename),pdf);
