function completeExcavatorSaleHandler(req,res,skipApproval=false){
  const b=excavatorGuard(req,res);if(!b)return;
  const a=db.prepare('SELECT a.*, xb.name buyer_name FROM excavator_assets a LEFT JOIN excavator_buyers xb ON xb.id=a.buyer_id WHERE a.id=? AND a.business_unit_id=?').get(req.params.id,b);
  if(!a)return res.status(404).json({error:'Machine not found'});
  if(a.lifecycle_stage==='Cancelled')return res.status(400).json({error:'Cancelled machines cannot be sold.'});

  const existingSale=db.prepare("SELECT * FROM excavator_transactions WHERE asset_id=? AND type IN ('Local Sale','Export Sale') AND status!='Cancelled' ORDER BY id DESC LIMIT 1").get(a.id),isUpdate=!!existingSale;
  if(a.lifecycle_stage==='Sold / Completed'&&!isUpdate)return res.status(400).json({error:'Sold/Completed machine has no editable sale transaction. Please inspect its history.'});
  const paidPurchase=Number(db.prepare("SELECT COALESCE(SUM(amount),0) total FROM excavator_payments WHERE asset_id=? AND payment_type='Purchase' AND status='Paid'").get(a.id).total||0);
  if(paidPurchase<Number(a.purchase_price||0))return res.status(400).json({error:'This machine cannot be sold until the complete purchase price has been paid.'});

  let saleType=String(req.body.sale_type||'').trim(),destination=String(req.body.destination_country||'').trim();
  const saleDate=String(req.body.sale_date||'').trim(),customer=String(req.body.customer_name||'').trim(),buyerId=req.body.buyer_id?Number(req.body.buyer_id):null,amount=num(req.body.selling_price),shipping=String(req.body.shipping_reference||'').trim(),sellNote=String(req.body.sell_note||'').trim();
  const selectedBuyer=buyerId?db.prepare('SELECT * FROM excavator_buyers WHERE id=? AND business_unit_id=? AND active=1').get(buyerId,b):null;
  if(buyerId&&!selectedBuyer)return res.status(400).json({error:'Invalid buyer selected.'});

  if(selectedBuyer){
    const c=String(selectedBuyer.country||'').trim().toLowerCase().replace(/\s+/g,' '),local=String(selectedBuyer.buyer_type||'').trim().toLowerCase()==='local'||['south korea','korea','republic of korea','korea, republic of','republic of korea (south korea)'].includes(c);
    saleType=local?'Local Sale':'Export Sale';destination=local?'':String(selectedBuyer.country||destination).trim();
  }
  if(!['Local Sale','Export Sale'].includes(saleType))return res.status(400).json({error:'Sale Type is required.'});
  if(!saleDate)return res.status(400).json({error:'Sale Date is required.'});
  if(!customer)return res.status(400).json({error:'Customer / Buyer is required.'});
  if(amount<=0)return res.status(400).json({error:'Selling Price is required and must be greater than zero.'});
  if(saleType==='Export Sale'&&!destination)return res.status(400).json({error:'Destination Country is mandatory for export sales.'});
  if(!shipping)return res.status(400).json({error:'Shipping / Container Reference is required.'});

  let paymentSource=String(req.body.payment_source||'').trim().toLowerCase();
  if(!['buyer_advance','new_payment'].includes(paymentSource))paymentSource=buyerId?'buyer_advance':'new_payment';
  if(!buyerId)paymentSource='new_payment';

  let paymentDate=String(req.body.payment_date||'').trim(),paymentReference=String(req.body.payment_reference||'').trim(),paymentMethod=String(req.body.payment_method||'').trim(),paymentCurrency=String(req.body.payment_currency||'KRW').toUpperCase(),paymentFx=paymentCurrency==='KRW'?1:num(req.body.payment_fx_rate);
  const evidenceFiles=req.files||[];
  const existingLinkedBuyerPayment=isUpdate?db.prepare("SELECT * FROM excavator_buyer_payments WHERE source_type='Excavator Sale' AND source_id=? AND COALESCE(status,'Active')!='Voided' ORDER BY id DESC LIMIT 1").get(existingSale.id):null;

  if(paymentSource==='buyer_advance'){
    if(!buyerId)return res.status(400).json({error:'Buyer advance can be used only for an existing buyer.'});
    paymentDate=saleDate;paymentReference='';paymentMethod='Buyer Advance';paymentCurrency='KRW';paymentFx=1;
  }else{
    if(!paymentDate)return res.status(400).json({error:'Payment Date is required when recording a new sale payment.'});
    if(!paymentReference)return res.status(400).json({error:'Payment Reference is required when recording a new sale payment.'});
    if(!paymentMethod)return res.status(400).json({error:'Payment Method is required when recording a new sale payment.'});
    if(paymentFx<=0)return res.status(400).json({error:'Conversion Rate to KRW is required.'});
    const canKeepExistingReceipt=!!(isUpdate&&existingLinkedBuyerPayment&&Number(existingLinkedBuyerPayment.buyer_id)===Number(buyerId||existingLinkedBuyerPayment.buyer_id)&&String(existingLinkedBuyerPayment.receipt_file||'').trim());
    if(!evidenceFiles.length&&!canKeepExistingReceipt)return res.status(400).json({error:'Receipt / evidence is mandatory when recording a new sale payment.'});
  }

  const cost=excavatorCostSnapshot(a.id),approvalTokens=[];let updateAuthorized=false;
  if(!skipApproval&&isUpdate){
    const ap=maybeCreateApproval({req,businessUnitId:b,actionKey:'completed_sale.update',type:'Update Completed Machine Sale',amount,reason:`Update ${a.asset_no} completed sale`,sourceEntity:'excavator_sale',sourceId:existingSale.id,priority:'High',snapshot:approvalRequestSnapshot(req,{business_unit_id:b,asset_id:a.id})});
    if(stopForApproval(res,ap,'Sale update submitted for approval. It will be applied automatically after final approval.'))return;
    if(ap.approval)approvalTokens.push(ap.approval);updateAuthorized=true;
  }
  if(!skipApproval&&!updateAuthorized&&amount<Number(cost?.total||0)){
    const ap=maybeCreateApproval({req,businessUnitId:b,actionKey:'sale.loss_or_low_margin',type:'Loss / Below-Margin Excavator Sale',amount,reason:`Sale price KRW ${amount} is below actual machine cost KRW ${Number(cost?.total||0)}`,sourceEntity:'excavator_asset',sourceId:a.id,priority:'Critical',snapshot:approvalRequestSnapshot(req,{business_unit_id:b,asset_id:a.id})});
    if(stopForApproval(res,ap,'Below-margin sale submitted for approval. It will be completed automatically after final approval.'))return;
    if(ap.approval)approvalTokens.push(ap.approval);
  }

  const execute=db.transaction(()=>{
    let finalBuyerId=buyerId,buyer;
    if(finalBuyerId){
      buyer=db.prepare('SELECT * FROM excavator_buyers WHERE id=? AND business_unit_id=? AND active=1').get(finalBuyerId,b);
      if(!buyer)throw new Error('Buyer not found.');
    }else{
      const buyerType=String(req.body.new_buyer_type||'International')==='Local'?'Local':'International',buyerName=String(req.body.new_buyer_name||customer).trim();
      const buyerCountry=String(req.body.new_buyer_country||(buyerType==='Local'?'South Korea':destination)||'').trim();
      if(!buyerName)throw new Error('New buyer name is required.');
      if(!buyerCountry)throw new Error('New buyer country is required.');
      const br=db.prepare(`INSERT INTO excavator_buyers(business_unit_id,name,country,location,contact_person,phone,whatsapp,email,address,payment_terms,notes,buyer_type,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)`)
        .run(b,buyerName,buyerCountry,req.body.new_buyer_location||'',req.body.new_buyer_contact_person||'',req.body.new_buyer_phone||'',req.body.new_buyer_whatsapp||'',req.body.new_buyer_email||'',req.body.new_buyer_address||'',req.body.new_buyer_payment_terms||'',req.body.new_buyer_notes||'',buyerType,req.user.id);
      finalBuyerId=Number(br.lastInsertRowid);buyer=db.prepare('SELECT * FROM excavator_buyers WHERE id=?').get(finalBuyerId);
    }

    if(isUpdate)db.prepare("UPDATE excavator_buyer_payment_allocations SET status='Reversed',void_reason='Sale update reallocation',voided_by=?,voided_at=CURRENT_TIMESTAMP WHERE asset_id=? AND COALESCE(status,'Active')='Active'").run(req.user.id,a.id);

    const metadata={destination_country:destination,shipping_reference:shipping,customer_name:customer,payment_source:paymentSource,payment_date:paymentDate,payment_reference:paymentReference,payment_method:paymentMethod,payment_currency:paymentCurrency,payment_fx_rate:paymentFx,sell_note:sellNote,buyer_id:finalBuyerId,buyer_payment_allocated_krw:amount,updated_sale:isUpdate};
    let saleId;
    if(isUpdate){
      saleId=existingSale.id;
      db.prepare(`UPDATE excavator_transactions SET type=?,stage='Sold / Completed',transaction_date=?,counterparty=?,amount=?,currency='KRW',status='Completed',notes=?,metadata=?,updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`)
        .run(saleType,saleDate,customer,amount,req.body.notes||'',JSON.stringify(metadata),req.user.id,saleId);
    }else{
      const rr=db.prepare(`INSERT INTO excavator_transactions(asset_id,type,stage,transaction_date,counterparty,amount,currency,status,notes,metadata,created_by,updated_by,updated_at) VALUES(?,?,?,?,?,?,'KRW','Completed',?,?,?,?,CURRENT_TIMESTAMP)`)
        .run(a.id,saleType,'Sold / Completed',saleDate,customer,amount,req.body.notes||'',JSON.stringify(metadata),req.user.id,req.user.id);
      saleId=Number(rr.lastInsertRowid);
    }

    let buyerPaymentId=null,buyerPaymentDocumentId=null;
    let linkedBuyerPayment=db.prepare("SELECT * FROM excavator_buyer_payments WHERE source_type='Excavator Sale' AND source_id=? AND COALESCE(status,'Active')!='Voided' ORDER BY id DESC LIMIT 1").get(saleId);

    if(paymentSource==='new_payment'){
      if(linkedBuyerPayment&&Number(linkedBuyerPayment.buyer_id)!==Number(finalBuyerId)){
        db.prepare("UPDATE excavator_buyer_payments SET status='Voided',notes=COALESCE(notes,'')||' | Voided because sale buyer changed.' WHERE id=?").run(linkedBuyerPayment.id);
        voidFinanceBySource('Excavator Buyer Payment',linkedBuyerPayment.id,'Sale buyer changed',req.user.id);
        linkedBuyerPayment=null;
      }
      const original=paymentCurrency==='KRW'?amount:amount/paymentFx,krw=paymentCurrency==='KRW'?amount:original*paymentFx,firstEvidence=evidenceFiles[0];
      if(linkedBuyerPayment){
        db.prepare(`UPDATE excavator_buyer_payments SET buyer_id=?,asset_id=?,payment_type='Sale Payment',original_amount=?,currency=?,fx_rate=?,krw_amount=?,payment_date=?,method=?,reference=?,receipt_file=COALESCE(?,receipt_file),notes=?,status='Active',source_type='Excavator Sale',source_id=? WHERE id=?`)
          .run(finalBuyerId,a.id,original,paymentCurrency,paymentFx,krw,paymentDate,paymentMethod,paymentReference,firstEvidence?.filename||null,isUpdate?'Updated from machine sale':'Created from completed machine sale',saleId,linkedBuyerPayment.id);
        buyerPaymentId=Number(linkedBuyerPayment.id);
      }else{
        const pr=db.prepare(`INSERT INTO excavator_buyer_payments(buyer_id,asset_id,payment_type,original_amount,currency,fx_rate,krw_amount,payment_date,method,reference,receipt_file,notes,status,created_by,source_type,source_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`)
          .run(finalBuyerId,a.id,'Sale Payment',original,paymentCurrency,paymentFx,krw,paymentDate,paymentMethod,paymentReference,firstEvidence?.filename||'','Created from completed machine sale','Active',req.user.id,'Excavator Sale',saleId);
        buyerPaymentId=Number(pr.lastInsertRowid);
      }
      if(evidenceFiles.length){
        const bd=db.prepare(`INSERT INTO excavator_buyer_documents(buyer_id,payment_id,asset_id,title,original_name,file_path,mime_type,size_bytes,uploaded_by) VALUES(?,?,?,?,?,?,?,?,?)`);
        for(const file of evidenceFiles){
          const dr=bd.run(finalBuyerId,buyerPaymentId,a.id,'Buyer Sale Payment Receipt / Evidence',file.originalname,'/uploads/'+file.filename,file.mimetype,file.size,req.user.id);
          buyerPaymentDocumentId=Number(dr.lastInsertRowid);
        }
        db.prepare('UPDATE excavator_buyer_payments SET receipt_document_id=? WHERE id=?').run(buyerPaymentDocumentId,buyerPaymentId);
      }else{
        buyerPaymentDocumentId=Number(db.prepare('SELECT receipt_document_id FROM excavator_buyer_payments WHERE id=?').get(buyerPaymentId)?.receipt_document_id||0)||null;
      }
      financeSync({businessUnitId:b,type:'Revenue',category:'Excavator Buyer Payment',amount:krw,description:'Buyer '+buyer.name+' sale payment for '+a.asset_no,paymentMethod,reference:paymentReference,createdBy:req.user.id,sourceType:'Excavator Buyer Payment',sourceId:buyerPaymentId,receiptFile:firstEvidence?.filename||linkedBuyerPayment?.receipt_file||'',originalAmount:original,originalCurrency:paymentCurrency,fxRate:paymentFx,transactionDate:paymentDate,sourceLabel:'Excavator → Buyer Payment',sourceRecordId:finalBuyerId,sourcePaymentId:buyerPaymentId});
      db.prepare(`INSERT INTO excavator_buyer_payment_allocations(payment_id,buyer_id,asset_id,amount_krw,allocation_date,created_by,notes,status) VALUES(?,?,?,?,?,?,?,'Active')`)
        .run(buyerPaymentId,finalBuyerId,a.id,amount,paymentDate,req.user.id,isUpdate?'Sale payment reallocated after sale update':'New sale payment allocated to machine');
    }else{
      if(linkedBuyerPayment){
        db.prepare("UPDATE excavator_buyer_payments SET status='Voided',notes=COALESCE(notes,'')||' | Voided because sale now uses buyer advance balance.' WHERE id=?").run(linkedBuyerPayment.id);
        voidFinanceBySource('Excavator Buyer Payment',linkedBuyerPayment.id,'Sale payment source changed to buyer advance',req.user.id);
      }
      const available=buyerGenericAdvanceAvailableForAsset(finalBuyerId,a.id);
      if(available+0.005<amount)throw new Error(`Buyer available advance is insufficient. Available: KRW ${available.toLocaleString()} / Required: KRW ${amount.toLocaleString()}. Record a buyer payment first or choose Record New Payment.`);
      let remaining=amount;
      const pays=db.prepare(`SELECT p.id,p.krw_amount,p.asset_id,COALESCE((SELECT SUM(al.amount_krw) FROM excavator_buyer_payment_allocations al WHERE al.payment_id=p.id AND COALESCE(al.status,'Active')='Active'),0) allocated
        FROM excavator_buyer_payments p
        WHERE p.buyer_id=? AND COALESCE(p.status,'Active')!='Voided'
          AND COALESCE(p.source_type,'')!='Excavator Sale'
          AND COALESCE(p.notes,'') NOT LIKE 'Created from %machine sale%'
        ORDER BY date(p.payment_date),p.id`).all(finalBuyerId);
      for(const p of pays){
        if(remaining<=0.005)break;
        const legacyUsed=p.asset_id&&Number(p.asset_id)!==Number(a.id)&&!Number(p.allocated||0),avail=Math.max(0,Number(p.krw_amount||0)-Number(p.allocated||0)-(legacyUsed?Number(p.krw_amount||0):0));
        if(avail<=0)continue;
        const take=Math.min(avail,remaining);
        db.prepare(`INSERT INTO excavator_buyer_payment_allocations(payment_id,buyer_id,asset_id,amount_krw,allocation_date,created_by,notes,status) VALUES(?,?,?,?,?,?,?,'Active')`)
          .run(p.id,finalBuyerId,a.id,take,saleDate,req.user.id,isUpdate?'Buyer advance reallocated after sale update':'Buyer advance allocated to machine sale');
        remaining-=take;
      }
      if(remaining>0.005)throw new Error('Unable to allocate enough buyer advance to this machine.');
    }

    let firstSaleEvidenceDocumentId=null;
    if(evidenceFiles.length){
      const evidenceIns=db.prepare('INSERT INTO excavator_documents(asset_id,stage,transaction_type,transaction_id,title,original_name,file_path,mime_type,size_bytes,uploaded_by) VALUES(?,?,?,?,?,?,?,?,?,?)');
      for(const file of evidenceFiles){
        const dr=evidenceIns.run(a.id,'Sold / Completed',saleType,saleId,'Machine Sale Payment Receipt / Evidence',file.originalname,'/uploads/'+file.filename,file.mimetype,file.size,req.user.id);
        if(firstSaleEvidenceDocumentId==null)firstSaleEvidenceDocumentId=Number(dr.lastInsertRowid);
      }
    }

    // Machine-side Sale payment mirrors confirmed payment coverage. It does not post a second
    // Finance entry; Finance already has the sale plus the underlying buyer cash receipt when applicable.
    const linkedMachinePayment=db.prepare("SELECT * FROM excavator_payments WHERE asset_id=? AND source_type='Excavator Sale' AND source_id=? ORDER BY id DESC LIMIT 1").get(a.id,saleId);
    const otherMachinePaid=Number(db.prepare("SELECT COALESCE(SUM(amount),0) v FROM excavator_payments WHERE asset_id=? AND payment_type='Sale' AND status='Paid' AND NOT (source_type='Excavator Sale' AND source_id=?)").get(a.id,saleId).v||0);
    const mirroredAmount=Math.max(0,amount-otherMachinePaid);
    let salePaymentId=null;
    if(mirroredAmount>0.005){
      const machineMethod=paymentSource==='buyer_advance'?'Buyer Advance':paymentMethod,machineReference=paymentSource==='buyer_advance'?'Buyer advance allocation':paymentReference,machineReceipt=paymentSource==='new_payment'?(evidenceFiles[0]?.filename||linkedMachinePayment?.receipt_file||''):'',machineDocId=paymentSource==='new_payment'?(firstSaleEvidenceDocumentId||linkedMachinePayment?.receipt_document_id||null):null,machineNote=paymentSource==='buyer_advance'?'Paid from buyer advance allocation; original payment evidence remains linked to the buyer advance ledger.':'Paid from the new buyer payment recorded during sale completion.';
      if(linkedMachinePayment){
        db.prepare(`UPDATE excavator_payments SET payment_type='Sale',amount=?,due_date=NULL,paid_date=?,status='Paid',method=?,reference=?,receipt_file=?,receipt_document_id=?,notes=?,created_by=COALESCE(created_by,?),buyer_id=?,payment_source=?,source_type='Excavator Sale',source_id=? WHERE id=?`)
          .run(mirroredAmount,paymentDate||saleDate,machineMethod,machineReference,machineReceipt,machineDocId,machineNote,req.user.id,finalBuyerId,paymentSource,saleId,linkedMachinePayment.id);
        salePaymentId=Number(linkedMachinePayment.id);
      }else{
        const mp=db.prepare(`INSERT INTO excavator_payments(asset_id,payment_type,amount,due_date,paid_date,status,method,reference,receipt_file,receipt_document_id,notes,created_by,source_type,source_id,buyer_id,payment_source) VALUES(?,'Sale',?,NULL,?,'Paid',?,?,?,?,?,?,'Excavator Sale',?,?,?)`)
          .run(a.id,mirroredAmount,paymentDate||saleDate,machineMethod,machineReference,machineReceipt,machineDocId,machineNote,req.user.id,saleId,finalBuyerId,paymentSource);
        salePaymentId=Number(mp.lastInsertRowid);
      }
    }else if(linkedMachinePayment&&linkedMachinePayment.status!=='Voided'){
      db.prepare("UPDATE excavator_payments SET status='Voided',notes=COALESCE(notes,'')||' | Auto mirror not required because other Sale payment records already cover the sale.' WHERE id=?").run(linkedMachinePayment.id);
    }

    const financeReference=paymentSource==='buyer_advance'?'Buyer advance allocation':paymentReference;
    const financeMethod=paymentSource==='buyer_advance'?'Buyer Advance':paymentMethod;
    const financeId=financeSync({businessUnitId:b,type:'Revenue',category:'Excavator Machine Sale',amount,description:'Excavator sale '+a.asset_no,paymentMethod:financeMethod,reference:financeReference,createdBy:req.user.id,sourceType:'Excavator Sale',sourceId:saleId,receiptFile:paymentSource==='new_payment'?(evidenceFiles[0]?.filename||''):'',resetVerification:isUpdate,originalAmount:paymentSource==='buyer_advance'?amount:(paymentCurrency==='KRW'?amount:amount/paymentFx),originalCurrency:paymentSource==='buyer_advance'?'KRW':paymentCurrency,fxRate:paymentSource==='buyer_advance'?1:paymentFx,transactionDate:saleDate,sourceLabel:'Excavator → Machine Sale',sourceRecordId:a.id});

    db.prepare("UPDATE excavator_assets SET selling_price=?,customer_id=NULL,buyer_id=?,status='Sold',lifecycle_stage='Sold / Completed' WHERE id=? AND business_unit_id=?").run(amount,finalBuyerId,a.id,b);
    markMatchingSupplierListingsSold(a);
    const lifecycleNote=paymentSource==='buyer_advance'?`${saleType} ${isUpdate?'sale updated':'completed'}; buyer advance allocated and payment marked paid`:`${saleType} ${isUpdate?'sale updated':'completed'}; new sale payment recorded and payment marked paid`;
    db.prepare('INSERT INTO excavator_lifecycle_events(asset_id,from_stage,to_stage,note,user_id) VALUES(?,?,?,?,?)').run(a.id,a.lifecycle_stage,'Sold / Completed',lifecycleNote,req.user.id);
    return {transaction_id:saleId,buyer_id:finalBuyerId,payment_source:paymentSource,advance_allocated_krw:amount,updated:isUpdate,finance_id:financeId,buyer_payment_id:buyerPaymentId,buyer_payment_document_id:buyerPaymentDocumentId,sale_payment_id:salePaymentId};
  });

  try{
    const result=execute(); // database commit completes before PDF generation starts
    const pdfResult=finalizeExcavatorSalePdf({assetId:a.id,businessUnitId:b,saleId:result.transaction_id,userId:req.user.id,language:req.headers['x-language']==='en'?'en':'ko'});
    for(const ap of approvalTokens)markApprovalExecuted(ap,req.user);
    notify(req.user.id,'info',isUpdate?'Excavator sale updated':'Excavator machine sold',`${a.asset_no} ${isUpdate?'sale updated':'sold to '+customer} for ${amount.toLocaleString()} KRW · payment fully covered.`,b,'excavator_asset',a.id,'excavator');
    audit(req.user,'excavator_sale',result.transaction_id,isUpdate?'update':'complete',JSON.stringify({asset:a.asset_no,saleType,amount,payment_source:result.payment_source,pdf_document_id:pdfResult.document_id,buyer_id:result.buyer_id,finance_id:result.finance_id,buyer_payment_id:result.buyer_payment_id,sale_payment_id:result.sale_payment_id,advance_allocated_krw:result.advance_allocated_krw,pdf_generated_after_commit:true}));
    res.json({ok:true,...result,...pdfResult,stage:'Sold / Completed',sale_payment_status:'Paid'});
  }catch(e){console.error('Excavator complete/update sale:',e);res.status(400).json({error:e.message})}
}

app.post('/api/excavator/assets/:id/complete-sale',auth,allow('sales','finance','purchases','inventory'),upload.array('payment_evidence',10),(req,res)=>completeExcavatorSaleHandler(req,res,false));

function executeApprovedExcavatorSale(approval,decider){
  const snapshot=storedApprovalSnapshot(approval),requester=storedApprovalUser(approval),body=snapshot.body||{};
  let assetId=Number(snapshot.asset_id||0);
  if(!assetId&&approval.source_entity==='excavator_asset')assetId=Number(approval.source_id||0);
  if(!assetId&&approval.source_entity==='excavator_sale')assetId=Number(db.prepare('SELECT asset_id FROM excavator_transactions WHERE id=?').get(approval.source_id)?.asset_id||0);
  if(!assetId)return {executed:false,error:'Approved machine sale is missing its linked machine.'};
  const request={params:{id:assetId},body,files:storedApprovalFiles(approval),file:null,user:requester,selected_business_unit_id:Number(approval.business_unit_id),headers:{'x-language':'ko'}};
  const result=captureInternalAction(response=>completeExcavatorSaleHandler(request,response,true)),payload=result.payload||{};
  if(!payload.transaction_id)return {executed:false,error:'Approved machine sale completed without a transaction identifier.'};
  db.prepare("UPDATE approvals SET source_entity='excavator_sale',source_id=?,execution_error='',updated_at=CURRENT_TIMESTAMP WHERE id=?").run(Number(payload.transaction_id),approval.id);
  markApprovalExecuted(approval,decider,{transaction_id:Number(payload.transaction_id),asset_id:assetId,buyer_id:payload.buyer_id,finance_id:payload.finance_id,document_id:payload.document_id});
  audit(decider,'approval',approval.id,'auto-execute-excavator-sale',JSON.stringify({asset_id:assetId,transaction_id:payload.transaction_id,requested_by:approval.requester_id}));
  return {executed:true,action:payload.updated?'Machine sale updated':'Machine sale completed',...payload};
}

app.post('/api/excavator/assets/:id/transactions',auth,allow('sales','purchases','inventory','finance'),upload.array('files',30),(req,res)=>{
  const b=excavatorGuard(req,res);if(!b)return;
  const a=excavatorAssetForAction(req,res,req.params.id,b,'Costs and transaction changes');if(!a)return;
  const type=String(req.body.type||'').trim(),stage=String(req.body.stage||a.lifecycle_stage||'Purchased').trim();
  const allowed=['Purchase','Logistics','Repair','Part Purchase','Part Used','Customs Duty','Tax / VAT','Shipping / Freight','Commission','Documentation / Clearance','Other Cost','Local Sale','Export Sale','Purchase Payment','Sale Payment'];
  if(!allowed.includes(type))return res.status(400).json({error:'Invalid transaction type'});
  const amount=num(req.body.amount);
  const files=req.files||[];
  const monetaryTypes=['Purchase','Logistics','Repair','Part Purchase','Customs Duty','Tax / VAT','Shipping / Freight','Commission','Documentation / Clearance','Other Cost','Local Sale','Export Sale','Purchase Payment','Sale Payment'];
  if(amount>0&&monetaryTypes.includes(type)&&!files.length)return res.status(400).json({error:'Receipt / evidence is mandatory for every payment-related Excavator entry.'});
  let metadata={};
  if(req.body.metadata){try{metadata=typeof req.body.metadata==='string'?JSON.parse(req.body.metadata):req.body.metadata}catch(e){metadata={}}}
  if(req.body.include_in_machine_cost!==undefined)metadata.include_in_machine_cost=String(req.body.include_in_machine_cost)==='1';
  const tx=db.transaction(()=>{
    const r=db.prepare('INSERT INTO excavator_transactions(asset_id,type,stage,transaction_date,counterparty,amount,currency,status,notes,metadata,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)').run(a.id,type,stage,req.body.transaction_date||null,req.body.counterparty||'',amount,req.body.currency||'KRW',req.body.status||'Open',req.body.notes||'',JSON.stringify({...metadata,finance_sync:true}),req.user.id);const costTypes=['Purchase','Logistics','Repair','Part Purchase','Customs Duty','Tax / VAT','Shipping / Freight','Commission','Documentation / Clearance','Other Cost'];if(costTypes.includes(type)&&amount>0)financeSync({businessUnitId:b,category:type,amount,description:a.asset_no+' '+type+(req.body.counterparty?' · '+req.body.counterparty:''),createdBy:req.user.id,sourceType:'Excavator Cost Transaction',sourceId:r.lastInsertRowid,receiptFile:files[0]?.filename||'',transactionDate:req.body.transaction_date||null});if(costTypes.includes(type))notify(req.user.id,'info','Excavator cost recorded',a.asset_no+': '+type+' · '+amount.toLocaleString()+' '+(req.body.currency||'KRW')+'.',b,'excavator_asset',a.id,'excavator');
    let documentCount=0;
    const ins=db.prepare('INSERT INTO excavator_documents(asset_id,stage,transaction_type,transaction_id,title,original_name,file_path,mime_type,size_bytes,uploaded_by) VALUES(?,?,?,?,?,?,?,?,?,?)');
    for(const f of files){ins.run(a.id,stage,type,r.lastInsertRowid,type+' supporting document',f.originalname,'/uploads/'+f.filename,f.mimetype,f.size,req.user.id);documentCount++}
    audit(req.user,'excavator_transaction',r.lastInsertRowid,'create',JSON.stringify({asset:a.asset_no,type,stage,amount,documentCount}));
    return {id:r.lastInsertRowid,document_count:documentCount};
  });
  try{res.json(tx())}catch(e){console.error('Excavator transaction:',e);res.status(400).json({error:e.message});}
});
app.put('/api/excavator/assets/:id/transactions/:txid',auth,allow('sales','purchases','inventory','finance'),upload.array('files',30),(req,res)=>{
  const b=excavatorGuard(req,res);if(!b)return;const a=excavatorAssetForAction(req,res,req.params.id,b,'Costs and transaction changes');if(!a)return;
  const x=db.prepare('SELECT * FROM excavator_transactions WHERE id=? AND asset_id=?').get(req.params.txid,a.id);if(!x)return res.status(404).json({error:'Transaction not found'});
  const type=String(req.body.type??x.type),amount=num(req.body.amount??x.amount),files=req.files||[],monetaryTypes=['Purchase','Logistics','Repair','Part Purchase','Customs Duty','Tax / VAT','Shipping / Freight','Commission','Documentation / Clearance','Other Cost','Local Sale','Export Sale','Purchase Payment','Sale Payment'];
  const existingEvidence=db.prepare("SELECT file_path FROM excavator_documents WHERE asset_id=? AND transaction_id=? AND COALESCE(file_path,'')<>'' ORDER BY id DESC LIMIT 1").get(a.id,x.id);
  if(amount>0&&monetaryTypes.includes(type)&&!files.length&&!existingEvidence)return res.status(400).json({error:'Receipt / evidence is mandatory for every payment-related Excavator entry.'});
  const metadata=req.body.metadata?(typeof req.body.metadata==='string'?(()=>{try{return JSON.parse(req.body.metadata)}catch(_){return{}}})():req.body.metadata):(()=>{try{return x.metadata?JSON.parse(x.metadata):{}}catch(_){return{}}})();
  db.prepare('UPDATE excavator_transactions SET type=?,stage=?,transaction_date=?,counterparty=?,amount=?,currency=?,status=?,notes=?,metadata=? WHERE id=?').run(type,req.body.stage??x.stage,req.body.transaction_date??x.transaction_date,req.body.counterparty??x.counterparty,amount,req.body.currency??x.currency,req.body.status??x.status,req.body.notes??x.notes,JSON.stringify({...metadata,finance_sync:true}),x.id);
  const ins=db.prepare('INSERT INTO excavator_documents(asset_id,stage,transaction_type,transaction_id,title,original_name,file_path,mime_type,size_bytes,uploaded_by) VALUES(?,?,?,?,?,?,?,?,?,?)');for(const f of files)ins.run(a.id,req.body.stage??x.stage,type,x.id,type+' supporting document',f.originalname,'/uploads/'+f.filename,f.mimetype,f.size,req.user.id);
  const costTypes=['Purchase','Logistics','Repair','Part Purchase','Customs Duty','Tax / VAT','Shipping / Freight','Commission','Documentation / Clearance','Other Cost'];if(costTypes.includes(type)&&amount>0)financeSync({businessUnitId:b,category:type,amount,description:a.asset_no+' '+type+((req.body.counterparty??x.counterparty)?' · '+(req.body.counterparty??x.counterparty):''),createdBy:x.created_by||req.user.id,sourceType:'Excavator Cost Transaction',sourceId:x.id,receiptFile:files[0]?.filename||(existingEvidence?.file_path?path.basename(existingEvidence.file_path):''),transactionDate:req.body.transaction_date??x.transaction_date,resetVerification:true});
  audit(req.user,'excavator_transaction',x.id,'update',JSON.stringify({...req.body,attachment_count:files.length}));res.json({ok:true,evidence:!!(files.length||existingEvidence)});
});
app.delete('/api/excavator/assets/:id/transactions/:txid',auth,allow('sales','purchases','inventory','finance'),(req,res)=>{const b=excavatorGuard(req,res);if(!b)return;const a=db.prepare('SELECT id,asset_no FROM excavator_assets WHERE id=? AND business_unit_id=?').get(req.params.id,b);if(!a)return res.status(404).json({error:'Machine not found'});const x=db.prepare('SELECT * FROM excavator_transactions WHERE id=? AND asset_id=?').get(req.params.txid,a.id);if(!x)return res.status(404).json({error:'Transaction not found'});const reason=String(req.body.reason||'').trim();if(!reason)return res.status(400).json({error:'Cancellation reason is required.'});const ap=maybeCreateApproval({req,businessUnitId:b,actionKey:'payment.void',type:'Void Excavator Cost / Transaction',amount:x.amount,reason,sourceEntity:'excavator_transaction',sourceId:x.id,priority:'Critical'});if(stopForApproval(res,ap,'Transaction reversal submitted for Finance + CEO approval. It will be applied automatically after final approval.'))return;db.prepare("UPDATE excavator_transactions SET status='Cancelled',notes=?,updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").run('CANCELLED: '+reason,req.user.id,x.id);voidFinanceBySource('Excavator Cost Transaction',x.id,reason,req.user.id);if(ap.approval)markApprovalExecuted(ap.approval,req.user);notify(req.user.id,'warning','Excavator cost cancelled',a.asset_no+': '+x.type+' was cancelled. Reason: '+reason,b,'excavator_asset',a.id,'excavator');audit(req.user,'excavator_transaction',x.id,'void',JSON.stringify({type:x.type,reason}));res.json({ok:true});});
app.put('/api/excavator/assets/:id/stage',auth,allow('sales','purchases','inventory','finance'),(req,res)=>{const b=excavatorGuard(req,res);if(!b)return;const a=db.prepare('SELECT a.*, b.name buyer_name FROM excavator_assets a LEFT JOIN excavator_buyers b ON b.id=a.buyer_id WHERE a.id=? AND a.business_unit_id=?').get(req.params.id,b);if(!a)return res.status(404).json({error:'Machine not found'});if(['Exported','Sold / Completed'].includes(req.body.stage))return res.status(400).json({error:'This stage is controlled by the machine sale workflow and cannot be selected manually.'}); if(!EX_STAGES.includes(req.body.stage))return res.status(400).json({error:'Invalid lifecycle stage'});const r=db.prepare('INSERT INTO excavator_lifecycle_events(asset_id,from_stage,to_stage,note,user_id) VALUES(?,?,?,?,?)').run(a.id,a.lifecycle_stage,req.body.stage,req.body.note||'',req.user.id);db.prepare('UPDATE excavator_assets SET lifecycle_stage=?,status=? WHERE id=?').run(req.body.stage,req.body.stage==='Sold / Completed'?'Sold':req.body.stage,a.id);audit(req.user,'excavator_asset',a.id,'stage_change',JSON.stringify({from:a.lifecycle_stage,to:req.body.stage}));res.json({ok:true,id:r.lastInsertRowid,stage:req.body.stage});});
