// V26 Buyer Management
function normalizeMachineText(value){return String(value||'').toLowerCase().replace(/[^a-z0-9가-힣]+/g,' ').trim()}
function smartTextScore(required,actual){const a=normalizeMachineText(required),b=normalizeMachineText(actual);if(!a)return 1;if(!b)return 0;if(a===b)return 1;if(a.includes(b)||b.includes(a))return .9;const at=new Set(a.split(/\s+/).filter(Boolean)),bt=new Set(b.split(/\s+/).filter(Boolean)),shared=[...at].filter(x=>bt.has(x)).length;return shared?shared/Math.max(at.size,bt.size):0}
function smartMachineMatch(requirement,machine){
  const checks=[];let earned=0,total=0;
  const text=(key,label,weight,machineKey=key)=>{const wanted=requirement[key];if(!String(wanted||'').trim())return;const score=smartTextScore(wanted,machine[machineKey]);total+=weight;earned+=weight*score;checks.push({field:key,label,matched:score>=.8,score:Math.round(score*100),wanted,actual:machine[machineKey]||''})};
  text('machine_name','Machine Name',15);text('machine_type','Machine Type',15);text('make','Make',15);text('model','Model',25);
  if(requirement.min_year||requirement.max_year){const year=Number(machine.year||0),ok=year>0&&(!requirement.min_year||year>=Number(requirement.min_year))&&(!requirement.max_year||year<=Number(requirement.max_year));total+=10;earned+=ok?10:0;checks.push({field:'year',label:'Year / Year Range',matched:ok,score:ok?100:0,wanted:`${requirement.min_year||'Any'}–${requirement.max_year||'Any'}`,actual:machine.year||''})}
  text('condition_status','Condition',10);
  if(requirement.budget_min||requirement.budget_max){const price=Number(machine.match_price??machine.asking_price??machine.selling_price??machine.purchase_price??0),ok=price>0&&(!requirement.budget_min||price>=Number(requirement.budget_min))&&(!requirement.budget_max||price<=Number(requirement.budget_max));total+=10;earned+=ok?10:0;checks.push({field:'budget',label:'Budget Range',matched:ok,score:ok?100:0,wanted:`${requirement.budget_min||0}–${requirement.budget_max||'Any'}`,actual:price})}
  const score=total?Math.round(earned/total*100):0,level=score>=90?'Exact Match':score>=65?'Close Match':'No Match';return {score,match_level:level,matched_fields:checks,matched:score>=65};
}
function persistRequirementMatches(requirementType,requirement,businessUnitId,machines){
  const source=requirementType==='Buyer'?'Supplier Listing':'Company Asset',active=[];
  for(const machine of machines){const result=smartMachineMatch(requirement,machine);if(!result.matched)continue;active.push(Number(machine.id));const buyerId=requirementType==='Buyer'?requirement.buyer_id:null,supplierId=requirementType==='Supplier'?requirement.supplier_id:machine.supplier_id||null;const insert=db.prepare(`INSERT OR IGNORE INTO excavator_requirement_matches(business_unit_id,requirement_type,requirement_id,machine_source,machine_id,buyer_id,supplier_id,score,match_level,matched_fields_json,status,notified_at) VALUES(?,?,?,?,?,?,?,?,?,?,'New',CURRENT_TIMESTAMP)`).run(businessUnitId,requirementType,requirement.id,source,machine.id,buyerId,supplierId,result.score,result.match_level,JSON.stringify(result.matched_fields));const match=db.prepare('SELECT * FROM excavator_requirement_matches WHERE requirement_type=? AND requirement_id=? AND machine_source=? AND machine_id=?').get(requirementType,requirement.id,source,machine.id);db.prepare("UPDATE excavator_requirement_matches SET score=?,match_level=?,matched_fields_json=?,status=CASE WHEN status='Expired' THEN 'New' ELSE status END,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(result.score,result.match_level,JSON.stringify(result.matched_fields),match.id);
    if(insert.changes){const ids=new Set([Number(requirement.created_by||0),Number(machine.created_by||0)].filter(Boolean)),owner=requirementType==='Buyer'?db.prepare('SELECT name FROM excavator_buyers WHERE id=?').get(requirement.buyer_id)?.name:db.prepare('SELECT name FROM excavator_suppliers WHERE id=?').get(requirement.supplier_id)?.name,machineLabel=machine.machine_name||`${machine.make||''} ${machine.model||''}`.trim()||`Machine #${machine.id}`,place=requirementType==='Buyer'?`${machine.supplier_name||'Supplier'} supplier section`:'company Excavator inventory',message=`${owner||'A customer'} requires ${machineLabel}; a ${result.match_level.toLowerCase()} (${result.score}%) is available in ${place}.`,targetId=requirementType==='Buyer'?requirement.buyer_id:requirement.supplier_id;for(const id of ids)notify(id,'info','Machine requirement match',message,businessUnitId,'requirement_match',match.id,requirementType==='Buyer'?'excavatorBuyers':'excavatorSuppliers',targetId)}
  }
  let expire="UPDATE excavator_requirement_matches SET status='Expired',updated_at=CURRENT_TIMESTAMP WHERE requirement_type=? AND requirement_id=? AND machine_source=? AND status='New'",args=[requirementType,requirement.id,source];if(active.length){expire+=` AND machine_id NOT IN (${active.map(()=>'?').join(',')})`;args.push(...active)}db.prepare(expire).run(...args);return active.length;
}
function buyerRequirementMatches(requirement,businessUnitId,{persist=true}={}){const machines=db.prepare(`SELECT sm.*,sm.asking_price match_price,s.name supplier_name,s.phone supplier_phone,s.email supplier_email FROM excavator_supplier_machines sm JOIN excavator_suppliers s ON s.id=sm.supplier_id WHERE s.business_unit_id=? AND s.active=1 AND sm.status='Available' ORDER BY sm.id DESC`).all(businessUnitId);if(persist&&requirement.id)persistRequirementMatches('Buyer',requirement,businessUnitId,machines);return machines.map(m=>{const result=smartMachineMatch(requirement,m),saved=requirement.id?db.prepare("SELECT id,status FROM excavator_requirement_matches WHERE requirement_type='Buyer' AND requirement_id=? AND machine_source='Supplier Listing' AND machine_id=?").get(requirement.id,m.id):null;return {...m,...result,match_id:saved?.id||null,match_status:saved?.status||''}}).filter(m=>m.matched).sort((a,b)=>b.score-a.score)}
function supplierRequirementMatches(requirement,businessUnitId,{persist=true}={}){const machines=db.prepare(`SELECT a.*,a.type machine_type,CASE WHEN COALESCE(a.selling_price,0)>0 THEN a.selling_price ELSE a.purchase_price END match_price FROM excavator_assets a WHERE a.business_unit_id=? AND a.status='Available' AND COALESCE(a.lifecycle_stage,'') NOT IN ('Sold / Completed','Cancelled') ORDER BY a.id DESC`).all(businessUnitId);if(persist&&requirement.id)persistRequirementMatches('Supplier',requirement,businessUnitId,machines);return machines.map(m=>{const result=smartMachineMatch(requirement,m),saved=requirement.id?db.prepare("SELECT id,status FROM excavator_requirement_matches WHERE requirement_type='Supplier' AND requirement_id=? AND machine_source='Company Asset' AND machine_id=?").get(requirement.id,m.id):null;return {...m,...result,match_id:saved?.id||null,match_status:saved?.status||''}}).filter(m=>m.matched).sort((a,b)=>b.score-a.score)}
function refreshBuyerRequirementMatchesForMachine(machineId,businessUnitId){const reqs=db.prepare(`SELECT r.* FROM excavator_buyer_requirements r JOIN excavator_buyers b ON b.id=r.buyer_id WHERE b.business_unit_id=? AND r.status='Active'`).all(businessUnitId);for(const r of reqs)buyerRequirementMatches(r,businessUnitId);return reqs.length}
function refreshSupplierRequirementMatchesForAsset(assetId,businessUnitId){const reqs=db.prepare(`SELECT r.* FROM excavator_supplier_requirements r JOIN excavator_suppliers s ON s.id=r.supplier_id WHERE s.business_unit_id=? AND r.status='Active'`).all(businessUnitId);for(const r of reqs)supplierRequirementMatches(r,businessUnitId);return reqs.length}
app.get('/api/excavator/buyers',auth,allow('dashboard','sales','purchases','finance'),(req,res)=>{const b=excavatorGuard(req,res);if(!b)return;const rows=db.prepare(`SELECT x.*, COALESCE((SELECT SUM(p.krw_amount) FROM excavator_buyer_payments p WHERE p.buyer_id=x.id AND p.status='Active'),0) total_paid_krw, COALESCE((SELECT SUM(al.amount_krw) FROM excavator_buyer_payment_allocations al JOIN excavator_buyer_payments ap ON ap.id=al.payment_id AND ap.status='Active' WHERE al.buyer_id=x.id AND COALESCE(al.status,'Active')='Active'),0)+COALESCE((SELECT SUM(p2.krw_amount) FROM excavator_buyer_payments p2 WHERE p2.buyer_id=x.id AND p2.status='Active' AND p2.asset_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM excavator_buyer_payment_allocations al2 WHERE al2.payment_id=p2.id AND COALESCE(al2.status,'Active')='Active')),0) allocated_krw, COALESCE((SELECT SUM(r.krw_amount) FROM excavator_buyer_refunds r WHERE r.buyer_id=x.id AND r.status='Completed'),0) refunded_krw, COALESCE((SELECT COUNT(*) FROM excavator_assets a WHERE a.buyer_id=x.id AND a.business_unit_id=x.business_unit_id),0) machine_count FROM excavator_buyers x WHERE x.business_unit_id=? AND x.active=1 ORDER BY x.name`).all(b).map(x=>({...x,unallocated_advance_krw:Math.max(0,Number(x.total_paid_krw||0)-Number(x.allocated_krw||0)-Number(x.refunded_krw||0))}));res.json(rows);});
