 const b=excavatorGuard(req,res);if(!b)return;const x=db.prepare('SELECT * FROM excavator_buyers WHERE id=? AND business_unit_id=?').get(req.params.id,b);if(!x)return res.status(404).json({error:'Buyer not found'});
 const payments=db.prepare(`SELECT p.*,a.asset_no,a.machine_name,COALESCE((SELECT SUM(al.amount_krw) FROM excavator_buyer_payment_allocations al WHERE al.payment_id=p.id AND COALESCE(al.status,'Active')='Active'),0) allocated_krw,CASE WHEN p.status='Voided' THEN 0 ELSE MAX(p.krw_amount-COALESCE((SELECT SUM(al.amount_krw) FROM excavator_buyer_payment_allocations al WHERE al.payment_id=p.id AND COALESCE(al.status,'Active')='Active'),0)-CASE WHEN p.asset_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM excavator_buyer_payment_allocations alx WHERE alx.payment_id=p.id AND COALESCE(alx.status,'Active')='Active') THEN p.krw_amount ELSE 0 END,0) END available_krw,(SELECT ap.id FROM approvals ap WHERE ap.source_entity='excavator_buyer_payment' AND ap.source_id=p.id AND ap.action_key='payment.void' AND ap.status IN ('Pending','Resubmitted','Changes Required','Approved') ORDER BY ap.id DESC LIMIT 1) pending_approval_id,(SELECT ap.status FROM approvals ap WHERE ap.source_entity='excavator_buyer_payment' AND ap.source_id=p.id AND ap.action_key='payment.void' AND ap.status IN ('Pending','Resubmitted','Changes Required','Approved') ORDER BY ap.id DESC LIMIT 1) pending_approval_status FROM excavator_buyer_payments p LEFT JOIN excavator_assets a ON a.id=p.asset_id WHERE p.buyer_id=? ORDER BY p.payment_date DESC,p.id DESC`).all(x.id);
