 const reqs=db.prepare('SELECT * FROM excavator_buyer_requirements WHERE buyer_id=? ORDER BY id DESC').all(x.id).map(r=>({...r,match_count:buyerRequirementMatches(r,b).length}));const docs=db.prepare('SELECT * FROM excavator_buyer_documents WHERE buyer_id=? ORDER BY id DESC').all(x.id);
