 const refunded=refunds.filter(r=>r.status==='Completed').reduce((sum,r)=>sum+Number(r.krw_amount||0),0);res.json({buyer:x,payments,refunds,machines,allocations,requirements:reqs,documents:docs,resale_shares:resaleShares,balance:{total_paid_krw:total,allocated_krw:allocated,refunded_krw:refunded,available_advance_krw:Math.max(0,total-allocated-refunded)},resale_profit_eligible:String(x.country||'').trim().toLowerCase()==='pakistan'});
