app.put('/api/excavator/exchange-proposals/:id',auth,allow('sales','purchases','finance'),(req,res)=>{const b=excavatorGuard(req,res);if(!b)return;const p=db.prepare('SELECT * FROM excavator_exchange_proposals WHERE id=? AND business_unit_id=?').get(req.params.id,b);if(!p)return res.status(404).json({error:'Exchange proposal not found'});const status=String(req.body.status??p.status);if(!['Draft','Proposed','Negotiating','Approved','Completed','Rejected','Cancelled'].includes(status))return res.status(400).json({error:'Invalid exchange proposal status'});const requested=Math.max(0,num(req.body.requested_machine_value??p.requested_machine_value)),offered=Math.max(0,num(req.body.offered_machine_value??p.offered_machine_value)),balance=Math.abs(requested-offered),direction=requested===offered?'Even Exchange':requested>offered?'Payable to machine owner':'Receivable from machine owner';db.prepare('UPDATE excavator_exchange_proposals SET requested_machine_value=?,offered_machine_value=?,balance_amount=?,balance_direction=?,inspection_condition=?,notes=?,status=?,reviewed_by=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(requested,offered,balance,direction,req.body.inspection_condition??p.inspection_condition,req.body.notes??p.notes,status,['Approved','Completed','Rejected'].includes(status)?req.user.id:p.reviewed_by,p.id);audit(req.user,'excavator_exchange_proposal',p.id,'update',JSON.stringify({status,balance,direction}));res.json({ok:true,status,balance_amount:balance,balance_direction:direction});});


app.get('/api/excavator/buyers/:id/resale-shares',auth,allow('dashboard','sales','purchases','finance'),(req,res)=>{const b=excavatorGuard(req,res);if(!b)return;const x=db.prepare('SELECT id,country FROM excavator_buyers WHERE id=? AND business_unit_id=?').get(req.params.id,b);if(!x)return res.status(404).json({error:'Buyer not found'});if(String(x.country||'').trim().toLowerCase()!=='pakistan')return res.status(403).json({error:'Resale Profit Share is available only for Pakistani buyers.'});res.json(db.prepare(`SELECT r.*,a.asset_no,a.machine_name,a.make,a.model FROM excavator_buyer_resale_shares r JOIN excavator_assets a ON a.id=r.asset_id WHERE r.buyer_id=? AND a.business_unit_id=? ORDER BY r.id DESC`).all(x.id,b));});
app.post('/api/excavator/buyers/:id/resale-shares',auth,allow('sales','finance','purchases'),upload.single('receipt'),(req,res)=>{const b=excavatorGuard(req,res);if(!b)return;const buyer=db.prepare('SELECT id,country FROM excavator_buyers WHERE id=? AND business_unit_id=?').get(req.params.id,b);if(!buyer)return res.status(404).json({error:'Buyer not found'});if(String(buyer.country||'').trim().toLowerCase()!=='pakistan')return res.status(403).json({error:'Resale Profit Share is available only for Pakistani buyers.'});const assetId=Number(req.body.asset_id||0);if(!assetId)return res.status(400).json({error:'Machine is required'});if(!db.prepare("SELECT id FROM excavator_assets WHERE id=? AND business_unit_id=? AND buyer_id=? AND lifecycle_stage='Sold / Completed'").get(assetId,b,buyer.id))return res.status(400).json({error:'Select a sold machine that belongs to this buyer.'});const existingResale=db.prepare('SELECT id FROM excavator_buyer_resale_shares WHERE buyer_id=? AND asset_id=? LIMIT 1').get(buyer.id,assetId);if(existingResale)return res.status(409).json({error:'A Pakistan resale profit-share record already exists for this machine. Edit the existing record instead.',duplicate_prevented:true,existing_record_id:existingResale.id});const resalePrice=num(req.body.resale_price_pkr),resaleProfit=num(req.body.resale_profit_pkr),sharePercent=num(req.body.share_percent),ourShare=num(req.body.our_share_pkr),received=num(req.body.amount_received_pkr),outstanding=Math.max(0,ourShare-received),receivedFlag=req.body.received==='1'||received>=ourShare&&ourShare>0?1:0;if((received>0||receivedFlag)&&!req.file)return res.status(400).json({error:'Receipt / evidence is mandatory when resale-profit payment is received.'});const tx=db.transaction(()=>{const r=db.prepare(`INSERT INTO excavator_buyer_resale_shares(buyer_id,asset_id,resale_price_pkr,resale_profit_pkr,share_percent,our_share_pkr,amount_received_pkr,outstanding_pkr,received,received_date,reference,receipt_file,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(buyer.id,assetId,resalePrice,resaleProfit,sharePercent,ourShare,received,outstanding,receivedFlag,req.body.received_date||null,req.body.reference||'',req.file?.filename||'',req.body.notes||'',req.user.id);let docId=null;if(req.file){const d=db.prepare(`INSERT INTO excavator_buyer_documents(buyer_id,asset_id,title,original_name,file_path,mime_type,size_bytes,uploaded_by) VALUES(?,?,?,?,?,?,?,?)`).run(buyer.id,assetId,'Buyer Resale Profit Share Receipt / Evidence',req.file.originalname,'/uploads/'+req.file.filename,req.file.mimetype,req.file.size,req.user.id);docId=d.lastInsertRowid;db.prepare('UPDATE excavator_buyer_resale_shares SET receipt_document_id=? WHERE id=?').run(docId,r.lastInsertRowid);}audit(req.user,'excavator_buyer_resale_share',r.lastInsertRowid,'create',JSON.stringify({asset_id:assetId,received_pkr:received,evidence:!!req.file}));return {id:r.lastInsertRowid,received:receivedFlag,outstanding_pkr:outstanding,receipt_document_id:docId};});try{res.json(tx())}catch(e){if(String(e.message||'').includes('Resale record already exists'))return res.status(409).json({error:'A Pakistan resale profit-share record already exists for this machine. Edit the existing record instead.',duplicate_prevented:true});throw e}});
app.put('/api/excavator/buyers/:id/resale-shares/:rid',auth,allow('sales','finance','purchases'),upload.single('receipt'),(req,res)=>{
  const b=excavatorGuard(req,res);if(!b)return;
  const r=db.prepare(`SELECT r.* FROM excavator_buyer_resale_shares r JOIN excavator_buyers x ON x.id=r.buyer_id WHERE r.id=? AND r.buyer_id=? AND x.business_unit_id=?`).get(req.params.rid,req.params.id,b);
  if(!r)return res.status(404).json({error:'Resale share record not found'});
  const received=num(req.body.amount_received_pkr??r.amount_received_pkr),share=num(req.body.our_share_pkr??r.our_share_pkr),outstanding=Math.max(0,share-received);
  const requestedFlag=req.body.received!==undefined?['1','true','yes','on'].includes(String(req.body.received).toLowerCase()):null;
  const flag=requestedFlag===null?(received>=share&&share>0?1:Number(r.received||0)):(requestedFlag?1:0);
  if((received>0||flag)&&!req.file&&!r.receipt_file)return res.status(400).json({error:'Receipt / evidence is mandatory when resale-profit payment is received.'});
  const tx=db.transaction(()=>{
    db.prepare(`UPDATE excavator_buyer_resale_shares SET resale_price_pkr=?,resale_profit_pkr=?,share_percent=?,our_share_pkr=?,amount_received_pkr=?,outstanding_pkr=?,received=?,received_date=?,reference=?,receipt_file=COALESCE(?,receipt_file),notes=? WHERE id=?`).run(num(req.body.resale_price_pkr??r.resale_price_pkr),num(req.body.resale_profit_pkr??r.resale_profit_pkr),num(req.body.share_percent??r.share_percent),share,received,outstanding,flag,req.body.received_date??r.received_date,req.body.reference??r.reference,req.file?.filename||null,req.body.notes??r.notes,r.id);
    let documentId=r.receipt_document_id||null;
    if(req.file){const d=db.prepare(`INSERT INTO excavator_buyer_documents(buyer_id,asset_id,title,original_name,file_path,mime_type,size_bytes,uploaded_by) VALUES(?,?,?,?,?,?,?,?)`).run(Number(req.params.id),r.asset_id,'Buyer Resale Profit Share Receipt / Evidence',req.file.originalname,'/uploads/'+req.file.filename,req.file.mimetype,req.file.size,req.user.id);documentId=Number(d.lastInsertRowid);db.prepare('UPDATE excavator_buyer_resale_shares SET receipt_document_id=? WHERE id=?').run(documentId,r.id);}
    audit(req.user,'excavator_buyer_resale_share',r.id,'update',JSON.stringify({received_pkr:received,evidence_uploaded:!!req.file}));
    return {ok:true,received:flag,outstanding_pkr:outstanding,receipt_document_id:documentId};
  });
  res.json(tx());
});
