// Basic scheduled alerts: run every 10 minutes while the server is active.
function alertSweep(){
  const overdue=db.prepare("SELECT id,owner_id,title,business_unit_id FROM tasks WHERE status NOT IN ('Completed','Cancelled') AND due_date IS NOT NULL AND date(due_date)<date('now')").all();
  overdue.forEach(t=>{if(!t.owner_id)return;const message=t.title;const exists=db.prepare("SELECT 1 FROM notifications WHERE user_id=? AND title='Overdue task' AND message=? AND COALESCE(business_unit_id,0)=COALESCE(?,0) AND date(created_at)=date('now')").get(t.owner_id,message,t.business_unit_id);if(!exists)notify(t.owner_id,'warning','Overdue task',message,t.business_unit_id,'task',t.id,'tasks');});
  const low=db.prepare("SELECT p.id,p.name,p.business_unit_id FROM products p WHERE p.active=1 AND p.item_type='PRODUCT' AND p.current_stock<=p.reorder_level AND p.reorder_level>0").all();
  low.forEach(p=>{const managers=db.prepare("SELECT id FROM users WHERE role IN ('CEO / Owner','Business Unit Manager','Operations Manager') AND active=1 AND (business_unit_id=? OR role='CEO / Owner')").all(p.business_unit_id);managers.forEach(m=>{const message=p.name;const exists=db.prepare("SELECT 1 FROM notifications WHERE user_id=? AND title='Low stock' AND message=? AND COALESCE(business_unit_id,0)=COALESCE(?,0) AND date(created_at)=date('now')").get(m.id,message,p.business_unit_id);if(!exists)notify(m.id,'warning','Low stock',message,p.business_unit_id,'product',p.id,'inventory');});});
}
setInterval(alertSweep,10*60*1000);setTimeout(alertSweep,3000);
app.get(/.*/,(req,res)=>res.sendFile(path.join(root,'public','index.html')));

function apiErrorHandler(err,req,res,next){
  console.error('API ERROR',req.method,req.originalUrl,err);
  if(res.headersSent)return next(err);
  if(String(req.path||'').startsWith('/api/')) return res.status(500).json({error:err.message||'Internal server error'});
  next(err);
}

app.use(apiErrorHandler);
app.listen(PORT,'0.0.0.0',()=>console.log(`Blue Ocean Market V30.16.0 running on port ${PORT}`));
